_COMPARTIR_DIAG_FILE = "/tmp/mw_compartir_diag.json"
_COMPARTIR_DIAG_TTL = 72 * 3600       # se olvidan solos a los 3 dias
_COMPARTIR_DIAG_BYTES = 2048          # un diagnostico de verdad ocupa ~300
_COMPARTIR_VIAS = ("compartir", "selector")
