# --- El aprendiz --------------------------------------------------------------
_APR_FILE = "/tmp/mw_aprende.json"        # quien lleva el turno (pid, ts)
_APR = {"turno": False, "rondas": 0, "dt": 0, "dx": 0, "wf": 0, "fallos": 0,
        "pendientes": -1, "ultimo": "", "ult_ts": 0, "refrescos": 0}
_APR_NEG = {}                    # clave -> (ts, segundos que no se reintenta)
_WF_CRUCE_T = [0.0]               # ultima vuelta del cruce WolfMax-DonTorrent (dtbl79)
_APR_T_DT = [0.0]                # ultimo PoW de DonTorrent pedido a una caja
_APR_T_REF = [0.0]               # ultimo refresco de conteos del Inicio
_APR_PAUSA = 45.0
_APR_PAUSA_DT = 120.0
# WolfMax: una huella cada 5 min como mucho, y dentro del cupo (ver
# _WF_CUPO_HORA): su web nueva cobra cada una como una descarga.
_APR_PAUSA_WF = 300.0
_APR_T_WF = [0.0]
_APR_RR = [0]
_APR_PID = [0]


def _apr_turno():
    """Solo UN worker aprende. Si el que lleva el turno muere (relevo,
    despliegue), a los 3 minutos lo coge el otro."""
    yo = os.getpid()
    now = _t.time()
    try:
        with _FileLock(_APR_FILE):
            try:
                with open(_APR_FILE, "r", encoding="utf-8") as f:
                    d = _json.load(f) or {}
            except Exception:
                d = {}
            if d.get("pid") not in (None, yo) and (now - d.get("ts", 0)) < 180:
                return False
            # las cuentas van aqui para que /catdiag las vea conteste el
            # worker que conteste (el otro no tiene el turno ni los numeros)
            d = {"pid": yo, "ts": now, "st": dict(_APR)}
            tmp = _APR_FILE + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                _json.dump(d, f)
            os.replace(tmp, _APR_FILE)
            return True
    except Exception:
        return False


def _cajas_libres():
    """Cajas vivas que NO estan reproduciendo. Un PoW de DonTorrent en una caja
    Android mientras mueve un 4K puede dar un tiron en la tele: al aprendiz no
    le corre ninguna prisa, asi que solo molesta a las que estan paradas."""
    vivas = _live_boxes(al_dia=True)     # al aprendiz, solo cajas al dia
    if not vivas:
        return []
    try:
        now = _t.time()
        suenan = {c for c, e in (_kbnow_load() or {}).items()
                  if (now - e.get("ts", 0)) < _KB_NOW_TTL and e.get("np")}
    except Exception:
        suenan = set()
    return [c for c in vivas if c not in suenan]


def _apr_caja():
    # Los huecos de "caja prestada" son 4 para todo el relay y una busqueda
    # puede usar 3: el aprendiz solo coge uno si deja 3 libres para la gente.
    try:
        if getattr(_BOX_LEND_SEM, "_value", 4) < 4:
            return None
    except Exception:
        pass
    libres = _cajas_libres()
    if not libres:
        return None
    _APR_RR[0] = (_APR_RR[0] + 1) % 1000000
    return libres[_APR_RR[0] % len(libres)]


# (dtbl125) LO QUE LA GENTE TIENE DELANTE. El aprendiz solo miraba el Inicio,
# asi que una busqueda ("dune") ensenaba sus tarjetas sin semillas para siempre
# salvo que alguien abriera cada ficha. Ahora /seedsknown apunta las claves que
# no supo contestar y el aprendiz las atiende ANTES que el resto del Inicio.
# No cambia CUANTO se pide (mismas pausas, mismo cupo de WolfMax, mismo PoW
# espaciado de DonTorrent): solo el ORDEN. Va en un fichero porque la web la
# sirve cualquiera de los dos workers y el aprendiz corre en el del turno.
_APR_BUSC_FILE = "/tmp/mw_aprbusc.json"
_APR_BUSC_TTL = 1800          # lo de hace mas de media hora ya no lo mira nadie
_APR_BUSC_MAX = 40


def _apr_busc_item(k):
    """De una clave de la web (sgKey) al item que entiende _apr_clave."""
    if k.startswith("dt:"):
        tb, _, cid = k[3:].partition(":")
        if tb == "peliculas" and cid.isdigit():
            return {"source": "dt", "tabla": tb, "content_id": cid,
                    "kind": "movie", "title": ""}
        return None
    if k.startswith("u:http"):
        from urllib.parse import urlparse as _up
        u = k[2:]
        host = (_up(u).hostname or "").lower()
        if "divxtotal" in host:
            return {"source": "dx", "url": u, "kind": "movie", "title": ""}
        if "wolfmax" in host:
            return {"source": "wf", "url": u, "kind": "movie", "title": ""}
    return None


def _apr_busc_lee():
    try:
        with open(_APR_BUSC_FILE, encoding="utf-8") as f:
            d = _json.load(f)
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


def _apr_busc_apunta(claves):
    """Claves sin semillas que acaba de pedir una pantalla. Barato: solo
    escribe si hay alguna nueva."""
    if not claves or os.environ.get("MW_APRENDIZ", "1") == "0":
        return
    try:
        now = _t.time()
        d = {k: v for k, v in _apr_busc_lee().items()
             if isinstance(v, (int, float)) and (now - v) < _APR_BUSC_TTL}
        nuevas = 0
        for k in claves[:20]:
            if k not in d and _apr_busc_item(k):
                d[k] = now
                nuevas += 1
        if not nuevas:
            return
        if len(d) > _APR_BUSC_MAX:
            d = dict(sorted(d.items(), key=lambda kv: -kv[1])[:_APR_BUSC_MAX])
        tmp = _APR_BUSC_FILE + ".%d" % os.getpid()
        with open(tmp, "w", encoding="utf-8") as f:
            _json.dump(d, f)
        os.replace(tmp, _APR_BUSC_FILE)
    except Exception:
        pass


def _apr_items_buscados(now):
    """Lo apuntado, lo mas reciente primero."""
    out = []
    for k, ts in sorted(_apr_busc_lee().items(), key=lambda kv: -(kv[1] or 0)):
        if isinstance(ts, (int, float)) and (now - ts) < _APR_BUSC_TTL:
            it = _apr_busc_item(k)
            if it:
                out.append(it)
    return out


def _apr_items_inicio():
    """Las PELICULAS del Inicio (Estrenos y Cine, en el orden en que se ven),
    con todas sus versiones: DonTorrent de la cache de /catbrowse y WolfMax y
    DivxTotal de la mezcla. La web decide despues que version gana cada
    tarjeta, asi que hay que saberlas todas."""
    out = []
    disco = None
    for kind in ("estrenos", "peliculas"):
        ent = _CATBROWSE_CACHE.get(kind + ":1")
        if not ent:
            if disco is None:
                disco = _catbrowse_load() or {}
            ent = disco.get(kind + ":1")
        mix = (_home_mix_cache(kind) or {}).get("items") or []
        for it in list((ent or {}).get("items") or []) + list(mix):
            if isinstance(it, dict) and it.get("kind") == "movie":
                out.append(it)
    return out


def _apr_clave(it):
    """(fuente, clave del almacen) -- la MISMA que usa la web (sgKey)."""
    s = it.get("source") or "dt"
    if s == "dt":
        cid = str(it.get("content_id") or "")
        tb = str(it.get("tabla") or "peliculas")
        if cid.isdigit() and _DTK_RE.match("%s:%s" % (tb, cid)):
            return "dt", "%s:%s" % (tb, cid)
        return None, None
    if s in ("dx", "wf"):
        u = str(it.get("url") or it.get("content_id") or "")
        if u.startswith("http"):
            return s, u
    return None, None


def _apr_pendientes(items, now):
    dtp = _dtpacked_load()
    dih = _dxih_load()
    out, vistos, ihs_viejos = [], set(), []
    sd = None
    libres = None                       # fichas de WolfMax sin huella (dtbl79)
    for it in items:
        src, k = _apr_clave(it)
        if not src or k in vistos:
            continue
        vistos.add(k)
        ih = ""
        if src == "dt":
            e = dtp.get(k) or {}
            if e.get("ih") and (now - e.get("ts", 0)) < _DTPACKED_TTL:
                ih = e["ih"]
                # (dtbl79) sabida pero sin nombre ni tamaño: se vuelve a pedir
                # SOLO si hay una ficha de WolfMax de ese titulo sin huella, y
                # no a cada vuelta si la caja aun no los sabe dar (2.9.90)
                if not e.get("b") and k.startswith("peliculas:") and not e.get("p"):
                    neg = _APR_NEG.get("nb:" + k)
                    if not (neg and (now - neg[0]) < neg[1]):
                        if libres is None:
                            libres = _wf_sin_huella()
                        if libres and _wf_cruce_falta(it.get("title") or "", libres):
                            out.append((src, k, it))
                            continue
                if e.get("s") is not None and (now - e.get("sts", 0)) < _SEEDS_TTL:
                    continue
        else:
            c = dih.get(k) or {}
            if len(str(c.get("ih") or "")) == 40 and (now - c.get("ts", 0)) < _DXIH_TTL:
                ih = c["ih"]
        if ih:
            if sd is None:
                sd = _seeds_load()
            e2 = sd.get(ih) or {}
            if (now - e2.get("ts", 0)) >= _SEEDS_TTL2:
                ihs_viejos.append(ih)
            continue
        neg = _APR_NEG.get(k)
        if neg and (now - neg[0]) < neg[1]:
            continue
        out.append((src, k, it))
    return out, ihs_viejos


def _apr_dt(k):
    """Infohash (+RAR y calidad) de una peli de DonTorrent, por una caja libre."""
    box = _apr_caja()
    if not box:
        return None
    sem = _lend_acquire(box)
    if sem is None:
        return None
    tb, cid = k.split(":", 1)
    try:
        job = "ap" + os.urandom(5).hex()
        _kb_enqueue(box, {"c": "etjob", "job": job, "op": "dtmeta",
                          "cid": cid, "tb": tb})
        res = _catjob_wait(job, 25.0)
    finally:
        _lend_release(sem)
    if res is None:
        return {"timeout": True}
    ih = _re_dt.sub(r"[^a-f0-9]", "", str(res.get("ih") or "").lower())[:40]
    out = {"ih": ih, "p": bool(res.get("rar")),
           "q": str(res.get("quality") or "")[:16]}
    # nombre y bytes del .torrent (cajas 2.9.90+): para reconocer el MISMO
    # torrent en WolfMax (dtbl79). Una caja anterior no los manda: no pasa nada.
    n = res.get("n")
    try:
        b = int(res.get("b") or 0)
    except (TypeError, ValueError):
        b = 0
    if isinstance(n, str) and n.strip() and 0 < b < 2 ** 50:
        out["n"], out["b"] = n.strip()[:200], b
    return out


def _apr_wf(url):
    if _wf_verif_activa():
        return None          # WolfMax pide verificacion humana (dtbl70)
    box = _apr_caja()
    if not box or not _box_wf_ok(box, _WF_TORRENT_MIN):   # que sepan sacar el torrent (dtbl67)
        return None
    sem = _lend_acquire(box)
    if sem is None:
        return None
    try:
        job = "ap" + os.urandom(5).hex()
        _kb_enqueue(box, {"c": "etjob", "job": job, "op": "infohash",
                          "src": "wf", "url": url})
        res = _catjob_wait(job, 25.0)
    finally:
        _lend_release(sem)
    if res is None:
        return {"timeout": True}
    ih = _re_dt.sub(r"[^a-f0-9]", "", str(res.get("ih") or "").lower())[:40]
    if len(ih) != 40 and res.get("link"):
        ih = _bounded(lambda: _ih_from_link(res.get("link") or ""), 10.0, "") or ""
    return {"ih": ih}


def _apr_dx(url):
    def _f():
        dls = (_dx_detail(url) or {}).get("downloads") or []
        return _ih_from_link(dls[0].get("torrent_url") or "") if dls else ""
    ih = _bounded(_f, 22.0, None)
    if ih is None:
        return {"timeout": True}
    return {"ih": ih or ""}


def _apr_guarda(src, k, r, now):
    ih = r["ih"]
    cuenta = _seed_counts_many([ih]).get(ih)
    if src == "dt":
        with _FileLock(_DTPACKED_FILE):
            d = _dtpacked_load()
            ent = d.get(k) or {}
            if ent.get("ih") and ent.get("ih") != ih:
                ent.pop("n", None)              # otro .torrent: su nombre ya no vale
                ent.pop("b", None)
            ent.update({"ih": ih, "p": r.get("p", ent.get("p", False)),
                        "q": r.get("q") or ent.get("q", ""), "ts": now})
            if r.get("n") and r.get("b"):
                ent["n"], ent["b"] = r["n"], r["b"]   # (dtbl79) solo aqui, no en la copia
            if cuenta is not None:
                ent["s"] = cuenta
                ent["sts"] = now
            d[k] = ent
            if len(d) > 3000:
                for kk in sorted(d, key=lambda kk: d[kk].get("ts", 0))[:len(d) - 3000]:
                    d.pop(kk, None)
            _dtpacked_save(d)
        if r.get("n") and r.get("b") and k.startswith("peliculas:"):
            try:
                _wf_cruce_dt()                   # ¿es el mismo de alguna ficha de WolfMax?
            except Exception:
                pass
        if k.startswith("series:"):
            try:
                _dt4k_apunta(k, ih, r.get("n"), r.get("b"))   # (dtbl82)
            except Exception:
                pass
    else:
        with _FileLock(_DXIH_FILE):
            d = _dxih_load()
            d[k] = {"ih": ih, "ts": now}
            if len(d) > 2000:
                for kk in sorted(d, key=lambda kk: d[kk].get("ts", 0))[:len(d) - 2000]:
                    d.pop(kk, None)
            _dxih_save(d)
        if src == "wf":         # y a su almacen propio, que no caduca (dtbl75)
            _wfih_apunta(k, ih, o="aprendiz", pisa=False)
    if cuenta is not None:
        _seeds_guarda({ih: cuenta}, now)


# --- Las Series 4K de DonTorrent, para los capitulos 4K de WolfMax (dtbl82) ------
# Medido el 02-11: de las 24 temporadas 4K mas nuevas de WolfMax, 14 estan en las
# Series 4K de DonTorrent con el MISMO archivo (misma huella y bytes en las 6
# comprobadas: Kill Jackie, Materia oscura, Marshals, VisionQuest...), y de sus
# 95 capitulos solo 13 se podian reproducir desde la tarjeta de WolfMax (el
# resto choca con su verificacion). El aprendiz aprende tambien esos capitulos de
# DonTorrent -- huella, nombre interno y bytes, por una caja libre y con la misma
# pausa que las pelis -- y los deja en la reserva de los ZIP: la tarjeta de
# WolfMax los empareja con la regla de siempre (_wf_casa: titulo + capitulo +
# tamaño exacto, y si hay duda, nada). Lo ya mirado queda en la copia de las
# huellas ("dt") para que un despliegue no lo repita. Solo en Render (o con
# MW_DT4K=1 en las pruebas): sin eso el aprendiz no sale de casa.
_DT4K_PAGINAS = ("/series/4k", "/series/4k/page/2", "/series/4k/page/3")
_DT4K_CADA = 3 * 3600            # la lista de temporadas 4K
_DT4K_TEMP_CADA = 12 * 3600      # cada temporada (van saliendo capitulos)
_DT4K_TEMP_RE = re.compile(r'href="(/serie/\d+/\d+/[^"<>\s]{1,160}?-\d{1,2}-Temporada-4k)"', re.I)
_DT4K = {"t_lista": 0.0, "temps": [], "vistas": {}, "pend": [], "lista_n": 0,
         "caps_vistos": 0, "aprendidos": 0, "a_reserva": 0, "fallos_html": 0,
         "alterna": 0}


def _dt4k_activo():
    return os.environ.get("MW_DT4K") == "1" or (
        _EN_RENDER and os.environ.get("MW_DT4K") != "0")


def _dt4k_html(path):
    """El HTML de una pagina de DonTorrent: desde Render y, si no, por una caja
    libre (su IP de casa). "" si no se pudo."""
    html = _bounded(lambda: (_cat_dt_session_get(path) or ("", None))[0], 10.0, "") or ""
    if html or _dt_caida_ya():
        return html
    box = _apr_caja()
    if not box:
        return ""
    sem = _lend_acquire(box)
    if sem is None:
        return ""
    try:
        j = "d4" + os.urandom(5).hex()
        _kb_enqueue(box, {"c": "etjob", "job": j, "op": "dthtml", "path": path})
        res = _catjob_wait(j, 20.0)
    finally:
        _lend_release(sem)
    h = (res or {}).get("html") or ""
    return "" if _dt_es_mantenimiento(h) else h


def _dt4k_pendientes(now):
    """Los capitulos de las Series 4K de DonTorrent aun sin aprender, como
    trabajos del aprendiz [("dt", "series:<id>", {title})]. Cada vuelta lee como
    mucho la lista (cada 3 h) o UNA temporada: esto no tiene ninguna prisa."""
    if not _dt4k_activo() or _dt_caida_ya():
        return []
    hechos = _wfih_actual().get("dt") or {}
    leida = False
    if (now - _DT4K["t_lista"]) >= _DT4K_CADA:
        _DT4K["t_lista"] = now
        leida = True
        temps = []
        for pg in _DT4K_PAGINAS:
            h = _dt4k_html(pg)
            if not h:
                _DT4K["fallos_html"] += 1
                break
            for p in _DT4K_TEMP_RE.findall(h):
                if p not in temps:
                    temps.append(p)
        if temps:
            _DT4K["temps"] = temps[:80]
            _DT4K["lista_n"] = len(temps)
    if not leida:
        for p in _DT4K["temps"]:
            if (now - _DT4K["vistas"].get(p, 0)) < _DT4K_TEMP_CADA:
                continue
            _DT4K["vistas"][p] = now
            h = _dt4k_html(p)
            if not h:
                _DT4K["fallos_html"] += 1
                break
            titulo, eps = _cat_parse_detail(h)
            ya = set(x[1] for x in _DT4K["pend"])
            for e in eps:
                k = "%s:%s" % (e.get("tabla") or "series", e.get("content_id"))
                if _WFIH_DTK.match(k) and k not in hechos and k not in ya:
                    _DT4K["pend"].append(("dt", k, {"title": "%s %s" % (titulo, e.get("label") or "")}))
                    _DT4K["caps_vistos"] += 1
            break                                  # una temporada por vuelta
    _DT4K["pend"] = [x for x in _DT4K["pend"] if x[1] not in hechos][-400:]
    out = []
    for x in _DT4K["pend"]:
        neg = _APR_NEG.get(x[1]) or _APR_NEG.get("nb:" + x[1])
        if not (neg and (now - neg[0]) < neg[1]):
            out.append(x)
    return out


def _dt4k_apunta(k, ih, n, b):
    """Un capitulo de DonTorrent aprendido: queda apuntado como mirado y, si es un
    capitulo en 4K, va a la reserva (y se ata ya si casa sin dudas con una ficha
    conocida de WolfMax). Devuelve True si fue a la reserva."""
    if not _WFIH_DTK.match(str(k)) or not _WFIH_IH.match(str(ih or "")):
        return False

    def _f(d):
        if d["dt"].get(k) == ih:
            return 0
        d["dt"][k] = ih
        return 1
    _wfih_cambia(_f)
    _DT4K["aprendidos"] += 1
    if not (isinstance(n, str) and n and isinstance(b, int) and b > 0):
        return False
    if not _wf_cap(n) or _wf_resol(n) != "2160":
        return False                               # solo capitulos 4K
    _wfih_de_zip([("DonTorrent-" + k, {"ih": ih, "n": n[:200], "b": b})], es_zip=False)
    _DT4K["a_reserva"] += 1
    return True


def _apr_ronda():
    """Una vuelta: como mucho UN trabajo. Devuelve cuanto esperar a la siguiente."""
    _APR["rondas"] += 1
    # Si el relay va cargado, no es el momento: esto no tiene ninguna prisa.
    if _BND_VIVOS[0] >= 12 or _thr.active_count() >= 70:
        return 90.0
    try:
        if _mem_cgroup_mb() >= 330:
            return 120.0
    except Exception:
        pass
    _bounded(_semillas_nube_sube, 25.0, 0)
    now = _t.time()
    # (dtbl79) las fichas de WolfMax que van llegando, contra lo ya aprendido
    # de DonTorrent: cada 10 min, sin pedir nada a nadie
    if (now - _WF_CRUCE_T[0]) >= 600:
        _WF_CRUCE_T[0] = now
        _bounded(_wf_cruce_dt, 20.0, 0)
    try:
        _busc = _apr_items_buscados(now)
    except Exception:
        _busc = []
    pend, viejos = _apr_pendientes(_busc + _apr_items_inicio(), now)
    # (dtbl82) los capitulos de las Series 4K, a turnos con los del Inicio: el
    # Inicio casi nunca se queda sin nada de DonTorrent (semillas que caducan,
    # fichas nuevas) y, solo detras, no les llegaba nunca la vez (medido en
    # produccion: 1 h, 0 capitulos). Un PoW para el Inicio, el siguiente para 4K.
    try:
        extra = _bounded(lambda: _dt4k_pendientes(now), 40.0, []) or []
        if extra:
            pend = (extra + pend) if _DT4K["alterna"] % 2 else (pend + extra)
    except Exception:
        pass
    _APR["pendientes"] = len(pend)
    # Los conteos del Inicio, frescos para quien abra la app (un paquete UDP
    # por tracker para todas, cada 40 min como mucho).
    if viejos and (now - _APR_T_REF[0]) >= 2400:
        _APR_T_REF[0] = now
        _seeds_guarda(_seed_counts_many(viejos[:140]))
        _APR["refrescos"] += 1
    _caida = _dt_caida_ya()     # DonTorrent caido: su PoW no puede salir bien
    for src, k, it in pend:
        if src == "dt" and (_caida or (now - _APR_T_DT[0]) < _APR_PAUSA_DT):
            continue            # el PoW de DonTorrent, espaciado: toca otra fuente
        if src == "wf" and ((now - _APR_T_WF[0]) < _APR_PAUSA_WF
                            or not _wf_url_nueva(k) or not _wf_cupo_toma()):
            continue            # WolfMax: espaciado y con cupo (dtbl49)
        if src == "wf":
            _APR_T_WF[0] = now
        if src == "dt":
            _APR_T_DT[0] = now
            _DT4K["alterna"] += 1            # (dtbl82) le toca al otro
            r = _apr_dt(k)
        elif src == "wf":
            r = _apr_wf(k)
        else:
            r = _apr_dx(k)
        if r is None:           # sin caja libre o sin hueco: otra vuelta
            continue
        _APR["ultimo"] = "%s %s" % (src, (it.get("title") or "")[:40])
        _APR["ult_ts"] = int(now)
        if len(str(r.get("ih") or "")) == 40:
            _apr_guarda(src, k, r, now)
            _APR[src] += 1
            if src == "dt" and not r.get("b"):
                # caja anterior a la 2.9.90: no sabe dar nombre y tamaño; no se
                # le vuelve a pedir ese hasta dentro de 12 h (dtbl79)
                _APR_NEG["nb:" + k] = (now, 12 * 3600)
        else:
            _APR["fallos"] += 1
            # que no conteste a tiempo no es lo mismo que "no hay .torrent"
            _APR_NEG[k] = (now, 1200 if r.get("timeout") else 6 * 3600)
            if len(_APR_NEG) > 3000:
                for kk in sorted(_APR_NEG, key=lambda kk: _APR_NEG[kk][0])[:1000]:
                    _APR_NEG.pop(kk, None)
        return _APR_PAUSA
    return 300.0 if not pend else 60.0


# --- EL VIGIA DE LAS FUENTES (dtbl53) ------------------------------------------
# Lo que se rompe en una fuente no da error: se ve vacio. El 28-09 WolfMax
# retoco su marcado y sus series llegaron sin capitulos sin que nada lo dijera;
# EliteTorrent llevaba dias sin calidad. Cada 3 h -- el worker que lleva el
# turno del aprendiz, aunque nadie use la app -- UNA busqueda de prueba en
# WolfMax, EliteTorrent y DivxTotal, y se mira que tenga buena pinta: que haya
# resultados, que traigan calidad, que las series traigan capitulos. /catdiag
# -> vigia: por fuente, la ultima mirada, desde cuando va mal y que falla.
# "dune" tiene pelis en varias calidades y series con capitulos en las tres.
_VIGIA_FILE = "/tmp/mw_vigia.json"
_VIGIA_CADA = 3 * 3600
_VIGIA_T = [0.0]
_VIGIA_Q = "dune"


def _vigia_lee():
    try:
        with open(_VIGIA_FILE, "r", encoding="utf-8") as f:
            return _json.load(f) or {}
    except Exception:
        return {}


def _vigia_juzga(src, items):
    """Buena pinta o no: lo que falla, en palabras."""
    problemas = []
    n = len(items)
    if n < 3:
        problemas.append("solo %d resultados" % n)
    con_q = sum(1 for x in items if (x.get("quality") or "").strip())
    pct = int(100 * con_q / n) if n else 0
    if src in ("wf", "et") and n and pct < 50:
        problemas.append("sin calidad (%d%% con calidad)" % pct)
    series_caps = None
    if src == "wf" and n:
        sueltos = sum(1 for x in items if _sin_serie(x))
        if sueltos:
            problemas.append("%d capitulos sin el nombre de su serie" % sueltos)
        g = _cat_group_episodes([dict(x) for x in items])
        series_caps = sum(1 for x in g if x.get("kind") == "serie" and x.get("eps"))
        if not series_caps:
            problemas.append("series sin capitulos")
    return {"n": n, "calidad_pct": pct, "series_con_caps": series_caps,
            "problemas": problemas}


def _vigia_busca(src, excluir=()):
    """(items, "", caja) o (None, por que no, caja). `excluir`: cajas que ya se
    probaron en esta ronda (para pedirselo a OTRA)."""
    if src == "dx":
        # DivxTotal devuelve [] AL INSTANTE con el disyuntor saltado: eso no es
        # "0 resultados", es que no contesto hace un momento (dtbl72)
        if _dx_is_down():
            return None, "DivxTotal no contesta a Render (disyuntor)", None
        its = _bounded(lambda: _dx_search_items(_VIGIA_Q, max_pages=1), 25.0, None)
        if its == [] and _dx_is_down():
            return None, "DivxTotal no contesta a Render (disyuntor)", None
        return (its, "", None) if its is not None else (None, "no contesto", None)
    if src == "wf":
        box = _box_wf("", excluir=excluir)
    elif excluir:
        box = next((b for b in _live_boxes(al_dia=True) if b not in excluir), None)
    else:
        box = _box_for("")
    if not box:
        return None, "sin caja al dia", None
    j = "vg" + os.urandom(5).hex()
    _kb_enqueue(box, {"c": "etjob", "job": j, "op": "search", "q": _VIGIA_Q,
                      "srcs": src})
    res = _catjob_wait(j, 30.0)
    if res is None:
        return None, "la caja no contesto", box
    return [x for x in (res.get("items") or []) if (x or {}).get("source") == src], "", box


_VIGIA_ARCHIVO_RE = re.compile(r"/(?:pelicula|serie/episodio|documental/episodio)/[a-z0-9]+/?$", re.I)


def _vigia_enlace(src, items):
    """Prueba el paso que usa la gente al dar a reproducir: sacar el enlace de
    UN archivo de los que salieron. "ok", "fallo", o None si no se pudo probar
    (sin cupo de WolfMax, sin archivo que probar). dtbl68."""
    if src == "wf":
        urls = [x.get("url") for x in items if _VIGIA_ARCHIVO_RE.search(x.get("url") or "")]
        if not urls or (not _wf_verif_activa() and not _wf_cupo_toma()):
            return None
    elif src == "et":
        urls = [x.get("url") for x in items if (x.get("url") or "").startswith("http")]
        if not urls:
            return None
    else:
        return None
    r = _resuelve_enlace("", src, urls[0], espera=25.0, cache=False)
    if r.get("link"):
        return "ok"
    if r.get("error") == "verificacion":
        return "verificacion"
    if r.get("error") in ("limite", "captcha"):
        return None          # su limite o su captcha: no es que este roto
    return "fallo"


def _vigia_ronda():
    """Una mirada a cada fuente. Se guarda en /tmp (lo lee /catdiag)."""
    out = _vigia_lee()
    now = int(_t.time())
    caidas = _fuentes_caidas()
    for src in ("wf", "et", "dx", "cb"):
        try:
            if src == "cb":
                juicio = _cb_vigia()        # cuentas, Telegram y dirección (dtbl119)
                if juicio is None:          # sin caja con la que mirar: no se sabe
                    continue
            elif src in caidas:
                juicio = {"n": 0, "problemas": ["caida (su web no responde)"], "caida": True}
            else:
                items, por, b1 = _vigia_busca(src)
                # Una caja que no contesta o que trae casi nada puede ser cosa
                # de SU casa (su ISP, una tele apagandose), no de la fuente. El
                # camino de la gente ya prueba otra caja; el vigia no, y apuntaba
                # un '-' sin mas. Antes de decir que va mal, OTRA caja (dtbl72).
                _dos = False
                if src in ("wf", "et") and b1 and (items is None or len(items) < 3):
                    it2, por2, b2 = _vigia_busca(src, excluir=(b1,))
                    if b2 and b2 != b1:
                        _dos = True
                        if it2 is not None and (items is None or len(it2) > len(items)):
                            items, por = it2, por2
                juicio = _vigia_juzga(src, items) if items is not None else \
                    {"n": 0, "problemas": [por]}
                if _dos:
                    juicio["cajas"] = 2
                if items:
                    en = _vigia_enlace(src, items)
                    if en:
                        juicio["enlace"] = en
                        if en == "verificacion":
                            juicio["problemas"].append(
                                "pide verificacion humana (captcha) en cada descarga: "
                                "se puede buscar, no reproducir")
                        if en == "fallo":
                            juicio["problemas"].append(
                                "no da el enlace para reproducir (fallaria cada capitulo)")
        except Exception as e:
            juicio = {"n": 0, "problemas": ["error %s" % type(e).__name__]}
        ok = not juicio["problemas"]
        antes = out.get(src) or {}
        rec = dict(juicio, ok=ok, ts=now)
        if not ok:
            rec["mal_desde"] = antes.get("mal_desde") if antes.get("ok") is False else now
        # El PORQUE del ultimo '-' se queda aunque la siguiente ronda vaya bien:
        # sin el, de un "+-+++-++" no habia forma de saber que habia fallado
        # (revision del 07-10) (dtbl72).
        if not ok:
            rec["ult_mal"] = {"ts": now, "problemas": list(juicio["problemas"]),
                              "n": juicio.get("n", 0), "cajas": juicio.get("cajas", 1)}
        elif antes.get("ult_mal"):
            rec["ult_mal"] = antes["ult_mal"]
        rec["historia"] = ((antes.get("historia") or "") + ("+" if ok else "-"))[-8:]
        out[src] = rec
    try:
        tmp = "%s.%d.tmp" % (_VIGIA_FILE, os.getpid())
        with open(tmp, "w", encoding="utf-8") as f:
            _json.dump(out, f)
        os.replace(tmp, _VIGIA_FILE)
    except Exception:
        pass
    return out


_WFV_REPASO = [0.0]


def _wf_verif_repasa():
    """Mientras WolfMax pide verificacion humana, se vuelve a mirar ANTES de que
    caduque la marca (a los 25 de sus 30 min). Sin esto, a la media hora el
    aviso de la web se iba y las tarjetas de WolfMax volvian a mandar hasta que
    alguien tropezaba con el captcha o pasaba el vigia (cada 3 h): parpadeaba.
    Y si WolfMax la quita, se sabe sin esperar a que nadie lo intente. Un
    trabajo de caja cada ~25 min y solo mientras dure (dtbl73)."""
    ts = float(_wf_verif_lee().get("ts") or 0)
    now = _t.time()
    if not ts or not ((_WF_VERIF_PAUSA - 300) <= (now - ts) <= 3 * 3600):
        return False
    if (now - _WFV_REPASO[0]) < 300:
        return False
    _WFV_REPASO[0] = now
    url = ""
    for c in ("movie", "tvshow"):
        url = next((x.get("url") for x in (_wfult_lee(c).get("items") or [])
                    if _VIGIA_ARCHIVO_RE.search(x.get("url") or "")), "")
        if url:
            break
    if not url:
        return False
    _resuelve_enlace("", "wf", url, espera=25.0, cache=False)
    return True


def _vigia_toca():
    """Cada 3 h, contando tambien lo que hizo el otro worker (fichero)."""
    ult = max(_VIGIA_T[0], max([float((v or {}).get("ts") or 0)
                                for v in _vigia_lee().values()] or [0]))
    if (_t.time() - ult) < _VIGIA_CADA:
        return False
    _VIGIA_T[0] = _t.time()
    return True


def _apr_bucle():
    _t.sleep(90 + _rnd_mem.random() * 30)      # que el arranque se asiente
    while True:
        pausa = _APR_PAUSA
        try:
            _APR["turno"] = _apr_turno()
            if _APR["turno"]:
                pausa = _apr_ronda()
                if _vigia_toca():
                    _vigia_ronda()          # el vigia de las fuentes (dtbl53)
                _wf_verif_repasa()          # la verificacion de WolfMax, al dia (dtbl73)
                # Tras un despliegue (/tmp vacio) lo ultimo de WolfMax no
                # esta: se pide ya, sin esperar a que alguien abra el Inicio y
                # le salga el plan B (dtbl64). Solo si esta VACIO: el refresco
                # normal sigue siendo cuando alguien mira.
                for _c in ("movie", "tvshow"):
                    if not (_wfult_lee(_c).get("items")):
                        _wfult_refresca(_c)
        except Exception:
            pausa = 120.0
        # A trozos, renovando el turno: con una pausa de 300 s el turno
        # caducaba a los 180 y el otro worker lo cogia -- se lo iban pasando
        # (lo enseñaba /catdiag, "turno" cambiando de uno a otro sin motivo).
        resto = pausa + _rnd_mem.random() * 10
        while resto > 0:
            trozo = min(resto, 120.0)
            _t.sleep(trozo)
            resto -= trozo
            if resto > 0 and _APR["turno"]:
                try:
                    _APR["turno"] = _apr_turno()
                except Exception:
                    pass


def _apr_arranca():
    """Se llama desde el primer request de cada worker (despues del fork, igual
    que el vigilante de memoria). Los dos workers tienen su hilo, pero solo el
    que lleva el turno trabaja."""
    if os.environ.get("MW_APRENDIZ", "1") == "0":
        return
    yo = os.getpid()
    if _APR_PID[0] == yo:
        return
    _APR_PID[0] = yo
    try:
        _kth.Thread(target=_apr_bucle, daemon=True).start()
    except Exception:
        pass


_CAT_BROWSE = {"estrenos": "/", "peliculas": "/peliculas", "series": "/series"}
_CATBROWSE_CACHE = {}      # "kind:page" -> {"items": [...], "ts": ...}
_CATBROWSE_TTL = 900       # 15 min: los listados cambian despacio
_CATBROWSE_DX_TTL = 300    # 5 min para el fallback DivxTotal -> reintenta DT pronto
_CATBROWSE_FILE = "/tmp/mw_catbrowse.json"   # persiste entre workers y deploys
_CATFEED_LAST = {}         # kind -> ts del ultimo empuje del box (diagnostico)

# Cache de BUSQUEDA. Una busqueda repetida o refinada (el usuario escribe, borra,
# reintenta, o vuelve atras) re-escrapeaba DonTorrent cada vez (~8s + suma riesgo
# de BANEO de la IP de Render = el dolor historico nº1). Con cache: el 2o hit es
# INSTANTANEO y NO toca DonTorrent/TMDB. TTL corto: un torrent nuevo no aparece
# minuto a minuto, 10 min es seguro. COMPARTIDA via disco (/tmp) como /catbrowse:
# con gthread hay 2 WORKERS (procesos) y la cache solo-memoria fallaba ~50% de las
# repeticiones (cada peticion puede caer en otro worker con su memoria vacia).
_CATSEARCH_CACHE = {}      # q.lower() -> {"items": [...], "ts": ...}
_CATSEARCH_TTL = 600       # 10 min
_CATSEARCH_MAX = 80        # tope de entradas -> no crece sin limite (Render 512MB)
_CATSEARCH_FILE = "/tmp/mw_catsearch.json"   # compartida entre workers
# Single-flight: query EN CURSO -> Event. Las peticiones identicas concurrentes
# (reintentos del front, varias pestañas) esperan a ESA en vez de abrir otro
# fan-out -> el relay no se satura. Por-worker (basta: los reintentos del mismo
# usuario caen casi siempre en el mismo worker; si no, paga 1 fan-out de mas, no se cuelga).
_CATSEARCH_INFLIGHT = {}
_CATSEARCH_INFLIGHT_LOCK = _thr.Lock()


def _catbrowse_load():
    try:
        with open(_CATBROWSE_FILE, "r", encoding="utf-8") as f:
            return _json.load(f) or {}
    except Exception:
        return {}


def _catbrowse_save(d):
    try:
        tmp = _CATBROWSE_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            _json.dump(d, f)
        os.replace(tmp, _CATBROWSE_FILE)
    except Exception:
        pass


# SEMILLA del catalogo (DonTorrent REAL) versionada en el repo. Es el "suelo"
# garantizado del Inicio: sobrevive a deploys, a /tmp borrado y a que el box este
# apagado -> el Inicio arranca SIEMPRE con DonTorrent (no con DivxTotal). Se
# refresca en vivo cuando el box empuja /catfeed o cuando Render alcanza DT; la
# semilla solo es el respaldo de ultimo-conocido. Cacheada en memoria (no cambia
# en runtime). Se regenera con GET /catdump tras un /catfeed bueno -> commit.
_CATBROWSE_SEED_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                    "catalog_seed.json")
_CATBROWSE_SEED_CACHE = [None]


def _catbrowse_seed():
    if _CATBROWSE_SEED_CACHE[0] is None:
        try:
            with open(_CATBROWSE_SEED_FILE, "r", encoding="utf-8") as f:
                _CATBROWSE_SEED_CACHE[0] = _json.load(f) or {}
        except Exception:
            _CATBROWSE_SEED_CACHE[0] = {}
    return _CATBROWSE_SEED_CACHE[0]


_SEED_META_INDEX = [None]


def _seed_meta_index():
    """Indice content_id -> {poster TMDB, year, rating} extraido de la semilla.
    Es una cache TMDB PERSISTENTE: cuando TMDB banea la IP de Render, el enrich
    reusa estos datos por content_id en vez de degradar el Inicio a la caratula
    no-HD. Solo guarda entradas con poster de TMDB (no thumbs de DonTorrent)."""
    if _SEED_META_INDEX[0] is None:
        idx = {}
        try:
            for ent in (_catbrowse_seed() or {}).values():
                for it in (ent or {}).get("items", []):
                    cid = it.get("content_id")
                    pos = it.get("poster") or ""
                    if cid and "image.tmdb.org" in pos:
                        idx[cid] = {"poster": pos, "year": it.get("year"),
                                    "rating": it.get("rating")}
        except Exception:
            pass
        _SEED_META_INDEX[0] = idx
    return _SEED_META_INDEX[0]


# Cache de ENRICH por content_id CONSTRUIDA desde lo que el BOX enriquece (su IP
# residencial SI alcanza TMDB; la de Render esta baneada). El box recibe `pending`
# en la respuesta de /catfeed, enriquece esos titulos y empuja /catenrich con
# {content_id: meta}. Aqui se acumula -> los siguientes /catfeed rellenan poster HD
# + nota + año al INSTANTE por content_id (sin tocar TMDB desde Render), aunque el
# box tarde en re-enriquecer. Persistente en /tmp (compartida entre workers); se
# pierde en deploy (la SEMILLA del repo es el suelo que sobrevive) -> promovible a
# la semilla con /catdump. Solo memoriza entradas con poster de TMDB.
_CAT_ENRICH_FILE = "/tmp/mw_cat_enrich.json"
_CAT_ENRICH_MAX = 4000     # tope de content_ids (Render 512MB)
_CAT_ENRICH_KEYS = ("poster", "year", "rating", "overview",
                    "backdrop", "genres", "tmdb_id",
                    # "title": el titulo OFICIAL que manda el box (addon 2.9.57+).
                    # Sin persistirlo aqui se perdia al guardar y las tildes no
                    # sobrevivian al siguiente /catfeed.
                    "title",
                    # addon 2.9.58+: leidos de la FICHA de DonTorrent (la fuente
                    # ORIGINAL). "dtok" marca que ese meta ya se resolvio contra
                    # la ficha —titulo real y, si habia homonimos, desempatados
                    # por director— asi que MANDA sobre cualquier match que el
                    # relay saque por su cuenta de TMDB, y no hay que re-pedirlo.
                    "dt_title", "dt_year", "dtok",
                    # addon 2.9.84+: version del emparejamiento con TMDB (ver
                    # _meta_rango). Sin ella, una SERIE es de antes y no manda.
                    "mv")


def _meta_rango(m):
    """Cuanto vale el meta que manda una caja: 2 = resuelto con la ficha de
    DonTorrent Y con el emparejamiento de la 2.9.84, 1 = con la ficha (`dtok`)
    pero el de antes, 0 = a ciegas."""
    m = m or {}
    if not m.get("dtok"):
        return 0
    try:
        return 2 if int(m.get("mv") or 0) >= 2 else 1
    except Exception:
        return 1


def _meta_fiable(m, kind):
    """El meta de la caja MANDA sobre lo que saque el relay de TMDB. Las SERIES,
    solo con el emparejamiento nuevo (dtbl59): con el de antes una serie recien
    estrenada perdia contra la PELICULA homonima con mas votos ("Brothers" 2026
    -> "Hermanos" 2009, "Historia de dos ciudades" 2026 -> la de 1935), y el
    relay, que busca las series COMO series, si acierta."""
    r = _meta_rango(m)
    return r >= 2 or (r == 1 and kind != "serie")


def _cat_enrich_load():
    try:
        with open(_CAT_ENRICH_FILE, "r", encoding="utf-8") as f:
            return _json.load(f) or {}
    except Exception:
        return {}


def _cat_enrich_store(meta):
    """Mezcla {content_id: meta} (solo entradas con poster TMDB) en la cache de
    disco, bajo lock entre procesos. Devuelve cuantas entradas se guardaron."""
    n = 0
    with _FileLock(_CAT_ENRICH_FILE):
        d = _cat_enrich_load()
        for cid, m in (meta or {}).items():
            if not isinstance(m, dict):
                continue
            if "image.tmdb.org" not in (m.get("poster") or ""):
                continue
            # NO DEGRADAR: si lo guardado ya se resolvio contra la ficha de
            # DonTorrent (`dtok`) y esto no, viene de un box ANTIGUO que solo
            # sabe preguntar a TMDB por el titulo -> es justo el match a ciegas
            # que pone el cartel del homonimo mas famoso. Con 7 cajas en el
            # sistema y actualizaciones escalonadas, sin esto una caja vieja
            # desharia en su siguiente vuelta lo que arreglo una nueva.
            if _meta_rango(d.get(str(cid))) > _meta_rango(m):
                continue
            d[str(cid)] = {k: m[k] for k in _CAT_ENRICH_KEYS if m.get(k) is not None}
            n += 1
        if len(d) > _CAT_ENRICH_MAX:   # no crecer sin limite
            for k in list(d.keys())[:-_CAT_ENRICH_MAX]:
                d.pop(k, None)
        try:
            tmp = _CAT_ENRICH_FILE + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                _json.dump(d, f)
            os.replace(tmp, _CAT_ENRICH_FILE)
        except Exception:
            pass
    if n:
        _ENRIQ_NUBE["cambios"] += n
        _enriq_nube_sube()
    return n


# --- Copia de las fichas del Inicio fuera de /tmp (dtbl65) ------------------
# Lo que las CAJAS resolvieron para cada titulo (cartel HD, año, nota, titulo
# con tildes, sinopsis) vivia solo en /tmp: tras cada despliegue el Inicio salia
# unos minutos sin tildes ("Un mundo frgil"), con carteles pequeños y sin fichas,
# hasta que las cajas lo volvian a mandar. Va al worker mw-sync, como las
# semillas: se LEE antes de escribir y se sube la UNION (nunca pisa la copia
# buena con un /tmp a medias), y un meta de mas rango nunca lo pisa uno de menos.
_ENRIQ_SYNC = "https://mw-sync.israeldm93.workers.dev/kv/enriq"
_ENRIQ_NUBE = {"subida_ts": 0.0, "vuelo": 0.0, "cambios": 0, "subidas": 0,
               "fallos": 0, "bajadas": 0, "recuperadas": 0, "bytes": 0}
_ENRIQ_TOPE_GZ = 900 * 1024          # el worker admite 1 MB (en base64)


def _enriq_valida(d):
    """Solo entradas con forma de meta: {cid: {poster de TMDB, ...}}."""
    out = {}
    for k, m in (d or {}).items():
        if isinstance(m, dict) and "image.tmdb.org" in str(m.get("poster") or ""):
            out[str(k)[:40]] = {kk: m[kk] for kk in _CAT_ENRICH_KEYS
                                if m.get(kk) is not None}
    return out


def _enriq_nube_lee():
    """La copia, validada. None si NO se pudo leer (que no es lo mismo que
    vacia: con None no se sube nada)."""
    try:
        import base64
        import gzip
        txt, st = _get_con_tope(_ENRIQ_SYNC, 10.0)
        if st != 200 or not txt:
            return None
        gz = (_json.loads(txt) or {}).get("gz")
        if not gz:
            return {}
        sobre = _json.loads(gzip.decompress(base64.b64decode(gz)).decode("utf-8")) or {}
        return _enriq_valida(sobre.get("m") or {})
    except Exception:
        return None


def _enriq_funde_local(remoto):
    """Lo de la copia que aqui no este (o este con menos rango), a /tmp."""
    if not remoto:
        return 0
    n = 0
    with _FileLock(_CAT_ENRICH_FILE):
        d = _cat_enrich_load()
        for cid, m in remoto.items():
            if cid in d and _meta_rango(d[cid]) >= _meta_rango(m):
                continue
            d[cid] = m
            n += 1
        if n:
            if len(d) > _CAT_ENRICH_MAX:
                for k in list(d.keys())[:-_CAT_ENRICH_MAX]:
                    d.pop(k, None)
            try:
                tmp = _CAT_ENRICH_FILE + ".tmp"
                with open(tmp, "w", encoding="utf-8") as f:
                    _json.dump(d, f)
                os.replace(tmp, _CAT_ENRICH_FILE)
            except Exception:
                return 0
    return n


def _enriq_empaqueta(d):
    """gzip+base64 de `d`; si no cabe, las mas RECIENTES que quepan (el orden
    del fichero es el de llegada). Devuelve (gz, cuantas)."""
    import base64
    import gzip
    items = list(d.items())
    while items:
        gz = base64.b64encode(gzip.compress(_json.dumps(
            {"v": 1, "m": dict(items)}).encode("utf-8"), 6)).decode("ascii")
        if len(gz) <= _ENRIQ_TOPE_GZ:
            return gz, len(items)
        items = items[len(items) // 5:]       # fuera el 20 % mas viejo
    return "", 0


def _enriq_sube_hilo():
    try:
        remoto = _enriq_nube_lee()
        if remoto is None:
            _ENRIQ_NUBE["fallos"] += 1
            return
        _ENRIQ_NUBE["recuperadas"] += _enriq_funde_local(remoto)
        union = dict(remoto)
        for cid, m in _enriq_valida(_cat_enrich_load()).items():
            if cid not in union or _meta_rango(m) >= _meta_rango(union[cid]):
                union.pop(cid, None)
                union[cid] = m                 # al final: lo mas reciente
        if not union:
            return
        gz, n = _enriq_empaqueta(union)
        if gz and _post_con_tope(_ENRIQ_SYNC, {"gz": gz}, 15.0) == 200:
            _ENRIQ_NUBE["subidas"] += 1
            _ENRIQ_NUBE["bytes"] = len(gz)
        else:
            _ENRIQ_NUBE["fallos"] += 1
    except Exception:
        _ENRIQ_NUBE["fallos"] += 1
    finally:
        _ENRIQ_NUBE["vuelo"] = 0.0


def _enriq_nube_sube(forzar=False):
    """Como mucho cada 10 min, solo si hubo cambios, en segundo plano y con
    tope (un requests a pelo contra Cloudflare puede colgar el hilo)."""
    try:
        if (not _EN_RENDER or os.environ.get("MW_SIN_NUBE") == "1") and not forzar:
            return 0
        ahora = _t.time()
        if not forzar and ((ahora - _ENRIQ_NUBE["subida_ts"]) < 600
                           or _ENRIQ_NUBE["cambios"] <= 0):
            return 0
        if _ENRIQ_NUBE["vuelo"] and (ahora - _ENRIQ_NUBE["vuelo"]) < 120:
            return 0
        _ENRIQ_NUBE["subida_ts"] = ahora
        _ENRIQ_NUBE["vuelo"] = ahora
        _ENRIQ_NUBE["cambios"] = 0
        _thr.Thread(target=_enriq_sube_hilo, daemon=True).start()
        return 1
    except Exception:
        _ENRIQ_NUBE["vuelo"] = 0.0
        return 0


def _enriq_nube_baja():
    """Al arrancar: lo de la copia, a /tmp (funde; nunca pisa algo mejor)."""
    got = _enriq_nube_lee()
    if got is None:
        return 0
    _ENRIQ_NUBE["bajadas"] += 1
    n = _enriq_funde_local(got)
    _ENRIQ_NUBE["recuperadas"] += n
    return n


def _enriq_arranca():
    if os.environ.get("MW_SIN_NUBE") == "1":      # las pruebas en local
        return

    def _ir():
        try:
            _t.sleep(4)
            n = _enriq_nube_baja()
            if n:
                print("[enriq] recuperadas %d fichas de la copia" % n, flush=True)
        except Exception:
            pass
    try:
        _thr.Thread(target=_ir, daemon=True).start()
    except Exception:
        pass


def _dt_title_fix(cur, dt_title, serie=False):
    """Titulo del listado (`cur`, mutilado por el slug de DonTorrent) corregido con
    el que publica la FICHA de DonTorrent (`dt_title`, con tildes). Devuelve None
    si no corresponden -> nunca se sustituye una peli por otra.

    SOLO restaura lo que el slug se come (acentos y puntuacion). NUNCA reescribe
    el formato del titulo: las fichas de SERIE titulan 'Sandokan - 1ª Temporada
    [1080p]' mientras el listado dice 'Sandokan 1 Temporada', y adoptar eso
    cambiaria el nombre de TODAS las series de golpe — con el titulo de clave
    que es (dedup de la busqueda, 'Mi lista' y capitulos vistos del movil), eso
    es justo lo que no se debe tocar. En series se sustituye unicamente el
    PREFIJO (lo anterior al ' - '), que es donde estan los acentos."""
    cur = (cur or "").strip()
    cand = _re_dt.sub(r"\s+", " ", (dt_title or "")).strip()
    if not cur or not cand or cand.lower() == cur.lower():
        return None          # igual salvo mayusculas -> no hay nada que ganar

    def _loose(s):
        # Mismo destrozo que hace el slug de DonTorrent (vocal acentuada FUERA)
        # y ademas sin la puntuacion que el slug tampoco conserva.
        return _re_dt.sub(r"[^a-z0-9]+", "", _dt_mutila(_dt_slug_apos(s)).lower())

    if serie:
        base = cand.split(" - ")[0].strip()
        if not base or _dt_mutila(base) == base:
            return None                          # sin acentos que restaurar
        mb = _dt_mutila(base)                    # el prefijo TAL COMO llega hoy
        if _loose(cur[:len(mb)]) == _loose(mb):
            return base + cur[len(mb):]
        return None
    if _loose(cand) == _loose(cur):
        return cand
    return None


def _cat_apply_meta(it, sm):
    """Aplica un meta TMDB (de la semilla o de la cache de enrich del box) a un
    item del Inicio. El meta va POR content_id (es la identidad de ESTE item),
    asi que sus campos MANDAN: antes solo se rellenaban los huecos y, si el item
    traia una ficha EQUIVOCADA de un match malo anterior (caso real: 'La
    residencia' con sinopsis/generos/backdrop/duracion de 'Asterix y la
    residencia de los dioses'), se corregia el poster pero la ficha ajena se
    quedaba PEGADA. Ahora se sobreescribe todo, y lo que el meta no traiga se
    QUITA: mejor sin dato que con el de otra peli. Devuelve True si puso un
    poster de TMDB."""
    if not sm or "image.tmdb.org" not in (sm.get("poster") or ""):
        return False
    it["poster"] = sm["poster"]
    # TILDES: DonTorrent no publica el titulo completo en sus listados (cada
    # ficha es un <a> con la imagen, sin title ni alt, y su propio slug viene
    # sin la vocal acentuada) -> el Inicio salia con 'Obsesin', 'Admisin
    # imposible', 'Cmplices hasta el final'. El titulo OFICIAL lo trae el BOX en
    # este meta (el relay no puede pedirlo: TMDB le banea la IP). Se aplica SOLO
    # si es el MISMO titulo salvo acentos (_dt_mutila) -> nunca sustituye una
    # peli por otra ni traduce al ingles (norma §0: espejo de la web original).
    _tt = (sm.get("title") or "").strip()
    _cur = (it.get("title") or "").strip()
    if _tt and _cur and _tt != _cur and _dt_mutila(_tt).lower() == _cur.lower():
        it["title"] = _tt
    # Mejor aun: el titulo de la FICHA de DonTorrent (addon 2.9.58+). Ese no hay
    # que validarlo contra TMDB porque viene de la web ORIGINAL, y cubre lo que
    # la via TMDB no podia: los titulos con PUNTUACION que el slug se come
    # ('Una Milla: Capítulo Uno' llegaba como 'Una Milla Captulo Uno' y la
    # comparacion letra a letra fallaba por los dos puntos).
    _fx = _dt_title_fix(it.get("title"), sm.get("dt_title"),
                        (it.get("kind") == "serie"))
    if _fx:
        it["title"] = _fx
    if sm.get("year"):
        it["year"] = sm["year"]
    if sm.get("rating") is not None:
        it["rating"] = sm["rating"]
    for k in ("overview", "backdrop", "genres", "tmdb_id"):
        if sm.get(k) is not None:
            it[k] = sm[k]
        else:
            it.pop(k, None)
    return True


# --- Cache de las fuentes que van POR CAJA (/catetbox) ----------------------
# Mismo motivo que _CATSEARCH_CACHE pero para EliteTorrent/WolfMax/DivxTotal-por
# -caja: cada peticion ocupa un hilo del relay ESPERANDO a un Kodi de casa (hasta
# 24s con WolfMax) y encima le da trabajo a la caja de otro. Repetir la misma
# busqueda (volver atras, otro amigo buscando lo mismo, un reintento) no puede
# volver a pagar eso. Compartida por disco: hay 2 workers.
_CATBOX_CACHE = {}
_CATBOX_TTL = 600          # 10 min con resultados
_CATBOX_TTL_EMPTY = 300    # 5 min si la caja contesto "no lo tengo" (es estable)
# ...salvo en WolfMax, donde el vacio NO es estable: la caja contesta [] cuando
# su crawl del catalogo no llega a tiempo (~88s en un titulo no indexado) y la
# serie SI esta en la web. Con 300s la joya de la casa quedaba tapada 5 minutos.
_CATBOX_TTL_EMPTY_WF = 60
_CATBOX_MAX = 120
_CATBOX_FILE = "/tmp/mw_catbox.json"


def _catbox_load():
    try:
        with open(_CATBOX_FILE, "r", encoding="utf-8") as f:
            return _json.load(f) or {}
    except Exception:
        return {}


def _catbox_save(d):
    try:
        tmp = _CATBOX_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            _json.dump(d, f)
        os.replace(tmp, _CATBOX_FILE)
    except Exception:
        pass


def _catbox_get(key):
    ent = _CATBOX_CACHE.get(key)
    if not ent:
        ent = _catbox_load().get(key)
        if ent:
            _CATBOX_CACHE[key] = ent
    if ent and (_t.time() - ent.get("ts", 0)) < ent.get("ttl", _CATBOX_TTL):
        return ent.get("items") or []
    return None


def _catbox_put(key, items):
    # la clave es "op|fuentes|consulta" (ver ckey en /catetbox)
    _srcs = (key.split("|") + ["", ""])[1].split(",")
    _empty_ttl = (_CATBOX_TTL_EMPTY_WF if "wf" in _srcs
                  else _CATBOX_TTL_EMPTY)
    rec = {"items": items, "ts": _t.time(),
           "ttl": _CATBOX_TTL if items else _empty_ttl}
    _CATBOX_CACHE[key] = rec
    try:
        disk = _catbox_load()
        disk[key] = rec
        if len(disk) > _CATBOX_MAX:
            for k in sorted(disk, key=lambda k: disk[k].get("ts", 0))[
                    :len(disk) - _CATBOX_MAX]:
                disk.pop(k, None)
        _catbox_save(disk)
    except Exception:
        pass
    if len(_CATBOX_CACHE) > _CATBOX_MAX:
        try:
            old = min(_CATBOX_CACHE, key=lambda k: _CATBOX_CACHE[k]["ts"])
            _CATBOX_CACHE.pop(old, None)
        except Exception:
            _CATBOX_CACHE.clear()


def _catsearch_load():
    try:
        with open(_CATSEARCH_FILE, "r", encoding="utf-8") as f:
            return _json.load(f) or {}
    except Exception:
        return {}


def _catsearch_save(d):
    try:
        tmp = _CATSEARCH_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            _json.dump(d, f)
        os.replace(tmp, _CATSEARCH_FILE)
    except Exception:
        pass


# === LISTA DE DESEADOS sincronizada (sin tocar fuentes -> CERO baneo) ========
# La lista vivia SOLO en localStorage del movil: si limpias el navegador,
# reinstalas la app o cambias de movil, se PERDIA. Aqui se guarda una copia
# ligada al codigo del box -> sobrevive y se puede ver desde otro dispositivo.
# El movil sigue siendo la copia MAESTRA (localStorage) y esto es espejo
# best-effort: la web hace UNION al cargar (NUNCA borra items -> imposible perder
# la lista por un fallo de sync). Solo guarda metadatos (titulo/poster/ids), nada
# de fuentes -> no puede contribuir a ningun baneo. /tmp se borra en deploy, pero
# el movil vuelve a subir su lista al cargar -> la copia se restaura sola.
_MYLIST_FILE = "/tmp/mw_mylist.json"
_MYLIST_MAX_ITEMS = 600      # tope por lista
_MYLIST_MAX_CODES = 50       # tope de codigos guardados
_MYLIST_LOCK = _thr.Lock()


def _mylist_load():
    try:
        with open(_MYLIST_FILE, "r", encoding="utf-8") as f:
            return _json.load(f) or {}
    except Exception:
        return {}


@app.get("/mylist")
def mylist_get():
    code = re.sub(r"\D", "", request.args.get("code", ""))[:6]
    if len(code) != 6:
        return jsonify({"list": [], "ts": 0})
    ent = _mylist_load().get(code) or {}
    # `listas` = los nombres de las listas propias del usuario (Mis listas). Va
    # por el mismo canal que la lista de siempre para que el movil y la tablet
    # vean los mismos nombres; si un cliente viejo no lo manda, se conserva.
    return jsonify({"list": ent.get("list", []), "ts": ent.get("ts", 0),
                    "listas": ent.get("listas", [])})


@app.post("/mylist")
def mylist_post():
    code = re.sub(r"\D", "", request.args.get("code", ""))[:6]
    if len(code) != 6:
        return jsonify({"ok": False}), 400
    body = request.get_json(silent=True) or {}
    lst = body.get("list")
    if not isinstance(lst, list):
        return jsonify({"ok": False}), 400
    lst = lst[:_MYLIST_MAX_ITEMS]
    listas = body.get("listas")
    if not isinstance(listas, list):
        listas = None                      # cliente viejo: no tocar lo guardado
    with _MYLIST_LOCK:
        d = _mylist_load()
        _ant = d.get(code) or {}
        d[code] = {"list": lst, "ts": _t.time(),
                   "listas": (listas[:40] if listas is not None
                              else _ant.get("listas", []))}
        if len(d) > _MYLIST_MAX_CODES:   # no crecer sin limite
            for k in list(d.keys())[:-_MYLIST_MAX_CODES]:
                d.pop(k, None)
        try:
            tmp = _MYLIST_FILE + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                _json.dump(d, f)
            os.replace(tmp, _MYLIST_FILE)
        except Exception:
            pass
    return jsonify({"ok": True, "n": len(lst)})


# El reloj del relay: 29 sitios lo usan para que una fuente lenta no cuelgue
# la peticion. Hasta dtbl06 lanzaba un HILO NUEVO cada vez y, al agotarse el
# presupuesto, lo abandonaba vivo. Medido en produccion: 15 hilos al arrancar,
# 56 a los pocos minutos de uso, y el RSS subiendo sin bajar nunca -- cada
# abandonado retiene su conexion, su scraper y su HTML a medio parsear. De ahi
# el aviso de Render del 15-09 ("exceeded its memory limit").
#
# Ahora los trabajos van a un POOL que se reutiliza y que NO puede crecer: si
# todos los huecos estan pillados por trabajos colgados, las llamadas nuevas
# devuelven su default sin crear nada. La app se degrada (esa busqueda sale con
# menos fuentes) en vez de morirse, que es justo el cambio que se busca.
# 40 y no 24: son 6 hilos de gunicorn y una busqueda puede pedir ~5 fuentes a
# la vez, asi que con 24 la sexta persona se quedaba sin huecos y su busqueda
# salia con menos fuentes -- justo lo que no puede pasar. Sigue siendo un tope,
# y a diez minutos de distancia de los ~380 hilos/hora que se fugaban.
_BND_MAX = 40
_BND_POOL = [None]          # se crea al primer uso (no en el import)
_BND_LOCK = _thr.Lock()
_BND_VIVOS = [0]            # trabajos en marcha ahora mismo
_BND_GEN = [0]              # generacion del pool (sube en cada recambio)
_BND_LLENO_DESDE = [0.0]    # desde cuando no queda ni un hueco
_BND_STATS = {"lanzados": 0, "abandonados": 0, "sin_hueco": 0, "pico": 0,
              "recambios": 0}
# id -> (linea que lo lanzo, cuando). Para saber QUE llamada se queda colgada
# sin repasar los 29 sitios a ojo: los que llevan mucho vivos salen en /catmem.
_BND_QUIEN = {}
_BND_SEQ = [0]
# El PRESUPUESTO VIAJA. Leccion repetida del proyecto: si el que llama se rinde
# a los 6 s pero la peticion de dentro no se entera, el trabajo sigue ocupando
# hueco, hilo y memoria un minuto mas. Hasta ahora habia que pasarlo a mano
# (`tope_s` de _dx_get); esto lo deja apuntado en el PROPIO HILO, asi que
# cualquier funcion de dentro puede preguntar cuanto le queda de verdad sin
# cambiar quince firmas.
_BND_LOCAL = _thr.local()


def _bnd_resto(defecto):
    """Segundos que le quedan al presupuesto del `_bounded` de este hilo.

    `defecto` si nadie lo acoto (llamada directa, hilo suelto). Nunca menos de
    medio segundo: cero significaria 'no lo intentes', y preferimos un intento
    corto a devolver la portada sin caratulas."""
    try:
        fin = getattr(_BND_LOCAL, "fin", 0.0)
        if fin:
            return max(0.5, min(float(defecto), fin - _t.time()))
    except Exception:
        pass
    return float(defecto)


def _bounded(fn, secs, default=None):
    """Ejecuta fn() con TOPE DURO de `secs`. Si tarda mas, devuelve `default` y
    sigue -> la peticion NUNCA se cuelga. El trabajo que se quedo atras ocupa un
    hueco del pool hasta que termine solo, pero ya no crea un hilo eterno."""
    with _BND_LOCK:
        if _BND_VIVOS[0] >= _BND_MAX:
            # Saturado: todos los huecos con trabajos que no vuelven. Antes esto
            # era justo el momento en que se creaban hilos a mansalva. Si sigue
            # asi, el vigilante estrena pool en ~1 min (_bnd_revisa).
            _BND_STATS["sin_hueco"] += 1
            if not _BND_LLENO_DESDE[0]:
                _BND_LLENO_DESDE[0] = _t.time()
            return default
        _BND_LLENO_DESDE[0] = 0.0
        _BND_VIVOS[0] += 1
        _BND_STATS["lanzados"] += 1
        if _BND_VIVOS[0] > _BND_STATS["pico"]:
            _BND_STATS["pico"] = _BND_VIVOS[0]
        gen = _BND_GEN[0]
        _BND_SEQ[0] += 1
        tid = _BND_SEQ[0]
        try:      # de donde sale esta llamada (fichero:linea del que la hace)
            _f = sys._getframe(1)
            _BND_QUIEN[tid] = ("%s:%d" % (_f.f_code.co_name, _f.f_lineno),
                               _t.time())
        except Exception:
            _BND_QUIEN[tid] = ("?", _t.time())
        # El pool se coge AQUI, con el mismo candado que la generacion: si se
        # cogiera fuera, un recambio entre medias meteria este trabajo en el
        # pool nuevo con la generacion vieja y al terminar no descontaria ->
        # un hueco perdido para siempre, y con los huecos se pierde el servicio.
        if _BND_POOL[0] is None:
            from concurrent.futures import ThreadPoolExecutor as _TPE
            _BND_POOL[0] = _TPE(max_workers=_BND_MAX, thread_name_prefix="bnd")
        pool = _BND_POOL[0]

    box = {"v": default}

    def _w():
        try:
            _BND_LOCAL.fin = _t.time() + max(0.1, float(secs))
        except Exception:
            pass
        try:
            box["v"] = fn()
        except Exception:
            box["v"] = default
        finally:
            try:
                _BND_LOCAL.fin = 0.0
            except Exception:
                pass
            # Solo descuenta si el pool sigue siendo el suyo: si hubo recambio,
            # este trabajo ya no cuenta para el tope del pool nuevo.
            with _BND_LOCK:
                _BND_QUIEN.pop(tid, None)
                if gen == _BND_GEN[0]:
                    _BND_VIVOS[0] -= 1

    try:
        fut = pool.submit(_w)
    except Exception:
        with _BND_LOCK:
            _BND_QUIEN.pop(tid, None)
            if gen == _BND_GEN[0]:
                _BND_VIVOS[0] -= 1
        return default
    try:
        fut.result(timeout=max(0.1, float(secs)))
    except Exception:
        # Se acabo el presupuesto (o reviento). Si aun no habia empezado lo
        # cancelamos: gastar una fuente para un resultado que ya nadie espera es
        # tirar tiempo de la caja y peticiones a la web de origen.
        _BND_STATS["abandonados"] += 1
        try:
            if fut.cancel():
                with _BND_LOCK:
                    _BND_QUIEN.pop(tid, None)
                    if gen == _BND_GEN[0]:
                        _BND_VIVOS[0] -= 1
        except Exception:
            pass
    return box["v"]


def _bnd_revisa():
    """Si el pool lleva ~1 min sin un hueco libre, estrena pool: mejor 24 hilos
    colgados en el viejo que un relay que responde a todo con su default."""
    try:
        with _BND_LOCK:
            desde = _BND_LLENO_DESDE[0]
            if not desde or (_t.time() - desde) < 60:
                return False
            viejo = _BND_POOL[0]
            _BND_GEN[0] += 1
            _BND_VIVOS[0] = 0
            _BND_LLENO_DESDE[0] = 0.0
            _BND_POOL[0] = None
            _BND_STATS["recambios"] += 1
            _BND_QUIEN.clear()
        try:      # sin esperar a los colgados: no volverian
            viejo.shutdown(wait=False)
        except Exception:
            pass
        print("[bnd] pool saturado -> recambio #%d" % _BND_STATS["recambios"],
              flush=True)
        return True
    except Exception:
        return False


# Un enriquecimiento de fondo por LISTADO, no uno por CAJA. Las cajas empujan
# los mismos tres listados cada ~8 minutos; el trabajo es identico y el
# resultado va a la misma clave de cache, asi que el segundo y siguientes solo
# servian para gastar hilos, memoria y llamadas a TMDB (que es quien nos banea).
# 6 min: por debajo del ciclo de las cajas, asi que cada ronda enriquece una vez.
_BGENR_VUELO = {}
_BGENR_TTL = 360.0


def _bgenr_pide(key):
    ahora = _t.time()
    with _ENR_LOCK:
        for k, ts in list(_BGENR_VUELO.items()):     # limpieza de los caducados
            if ahora - ts > _BGENR_TTL:
                _BGENR_VUELO.pop(k, None)
        if (ahora - _BGENR_VUELO.get(key, 0.0)) < _BGENR_TTL:
            return False
        _BGENR_VUELO[key] = ahora
        return True


@app.post("/catfeed")
def catfeed():
    """El box PRE-CARGA los listados de DonTorrent (que Render no alcanza por el
    baneo de IP) desde su IP residencial y los empuja aqui; los parseamos +
    cacheamos -> catbrowse los sirve al INSTANTE. Inicio funciona y rapido aunque
    Render este baneado, sin esperar a ningun on-demand."""
    try:
        body = request.get_json(silent=True) or {}
    except Exception:
        body = {}
    kind = (body.get("kind") or "").strip().lower()
    html = body.get("html") or ""
    # El box 2.9.58+ sabe leer la FICHA de DonTorrent (titulo real + director) y
    # lo anuncia aqui. Cambia a quien se le pide enrich (ver mas abajo): a un box
    # que NO sabe no tiene sentido pedirle lo que no puede resolver.
    box_ficha = bool(body.get("ficha"))
    if kind not in _CAT_BROWSE or len(html) < 500:
        return jsonify({"ok": False}), 400
    try:
        raw = _cat_parse_items(html)
    except Exception:
        raw = []
    if not raw:
        # Las cajas empujan su listado cada ~8 min: si lo que traen es la
        # pagina de mantenimiento de DonTorrent, el relay se entera por ellas.
        if _dt_es_mantenimiento(html):
            _dt_caida_apunta(True, 503, "caja")
        return jsonify({"ok": False, "items": 0})
    # Cachea YA con la caratula PROPIA de DonTorrent (poster=thumb) -> catbrowse
    # sirve al INSTANTE en cuanto el box empuja. El enrich TMDB (en frio ~40s, si
    # TMDB ralentiza la IP de Render) va en 2o plano y MEJORA posters/notas SIN
    # bloquear el POST del box (antes el POST esperaba el enrich -> ReadTimeout
    # -> 0/3 -> Inicio vacio). Asi el POST responde en ~1s y nunca falla por eso.
    key = "%s:1" % kind
    # Rellena con el TMDB de la SEMILLA por content_id (caratula HD + nota + año)
    # de forma SINCRONA: el box empuja HTML crudo y Render no puede enriquecer
    # (TMDB le banea la IP) -> sin esto el Inicio se DEGRADABA a la caratula propia
    # no-HD. No depende del hilo de fondo (que en Render free puede no completar).
    seed_idx = _seed_meta_index()
    enr_idx = _cat_enrich_load()    # cache TMDB por content_id construida por el BOX
    pending = []                    # items sin poster TMDB -> el box los enriquece
    for it in raw:
        cid = it.get("content_id")
        sm = seed_idx.get(cid) or enr_idx.get(str(cid))
        _viejo = it.get("kind") == "serie" and _meta_rango(sm) == 1
        _ok = False if _viejo else _cat_apply_meta(it, sm)
        # Se pide enrich al box si falta el POSTER o si el meta guardado aun no
        # esta resuelto contra la FICHA de DonTorrent. Sin lo segundo nada de lo
        # que solo publica la ficha llegaria jamas: los metas viejos (cache
        # acumulada) ya tenian poster, asi que NINGUN item entraba en `pending`
        # y el box no enriquecia nada. Es autolimitado —en cuanto el meta trae
        # la marca deja de pedirse— y la marca depende de LO QUE SEPA el box:
        # a uno antiguo se le sigue pidiendo solo hasta que manda `title`, que
        # es todo lo que puede dar (si no, se le pediria en cada vuelta).
        _done = (_meta_fiable(sm, it.get("kind"))
                 or (not box_ficha and (sm or {}).get("title")))
        if (not _ok) or not _done:
            if not it.get("poster"):
                it["poster"] = it.get("thumb")
            if len(pending) < 80:    # candidatos a enrich por el box (TMDB no baneado)
                p = {"cid": cid, "title": it.get("title"),
                     "kind": it.get("kind")}
                if it.get("dtpath") or it.get("path"):
                    # Ruta de la ficha CON SLUG (DonTorrent da 404 por id pelado).
                    p["dtpath"] = it.get("dtpath") or it.get("path")
                pending.append(p)
    rec = {"items": raw, "ts": _t.time()}
    _CATBROWSE_CACHE[key] = rec
    _CATFEED_LAST[kind] = _t.time()
    try:
        disk = _catbrowse_load()
        disk[key] = rec
        _catbrowse_save(disk)
    except Exception:
        pass

    def _bg_enrich(_its=[dict(_x) for _x in raw], _key=key,
                   _wait=(45.0 if box_ficha else 0.0)):
        try:
            # Si el box sabe leer la FICHA, se le DEJA LLEGAR PRIMERO: tarda unos
            # 25 s (ficha + TMDB desde su IP) y trae el match bueno. Sin esta
            # espera los dos caminos corrian a la vez y, cuando ganaba este, el
            # Inicio se quedaba varios minutos con el cartel del homonimo famoso
            # hasta el siguiente /catfeed. Con la espera, cuando este hilo
            # arranca los metas del box ya estan puestos y _cat_enrich ni toca
            # TMDB para ellos. Se mantiene como PLAN B (§9: ninguna funcion de
            # red con un solo camino) por si el box no logra enriquecer.
            if _wait:
                _t.sleep(_wait)
            # Va en 2o plano (no bloquea el POST del box), pero igualmente
            # acotado: con TMDB baneando a Render este hilo se eternizaba
            # consumiendo CPU/red del proceso. 40s y a otra cosa.
            # Los items llegan YA PARSEADOS (copiados antes de lanzar el hilo).
            # Antes se traia el HTML entero en el closure y se re-parseaba aqui:
            # con varias cajas empujando a la vez eso eran varios HTML de cientos
            # de KB retenidos 45 s -- y el parseo repetido, gratis para nadie.
            en = _bounded(lambda: _cat_enrich(_its), 40.0, default=None)
            if en:
                # No DEGRADAR: mientras este hilo corria (~40s con TMDB baneado),
                # el box pudo empujar /catenrich con posters HD. _cat_enrich solo
                # mira la semilla, asi que sin esto su resultado PISABA esos
                # posters al escribir la cache -> el Inicio parpadeaba a no-HD.
                enr = _cat_enrich_load()
                for it in en:
                    _m = enr.get(str(it.get("content_id"))) or {}
                    # El meta con `dtok` esta resuelto contra la FICHA de
                    # DonTorrent (titulo real y homonimos desempatados por
                    # director): MANDA siempre sobre lo que el relay saque de
                    # TMDB a ciegas, que es justo lo que ponia el cartel de la
                    # peli equivocada ('La odisea' -> la de Nolan).
                    if _meta_fiable(_m, it.get("kind")) or \
                            "image.tmdb.org" not in (it.get("poster") or ""):
                        _cat_apply_meta(it, _m)
                r2 = {"items": en, "ts": _t.time()}
                _CATBROWSE_CACHE[_key] = r2
                d = _catbrowse_load()
                d[_key] = r2
                _catbrowse_save(d)
        except Exception:
            pass
    if pending and _bgenr_pide(key):
        # sin pendientes = todo ya en HD por semilla/cache del box -> el
        # re-enrich de fondo (que ademas toca TMDB desde Render) no aporta nada.
        # Y `_bgenr_pide` es lo que impide la avalancha: HAY OCHO CAJAS y todas
        # empujan los MISMOS tres listados cada ~8 min. Antes cada POST lanzaba
        # su hilo -> hasta 24 hilos durmiendo 45 s y despues 8 sub-hilos cada uno
        # para enriquecer EXACTAMENTE LO MISMO. Ahi estaban los 179 y 204 hilos
        # que obligaron a relevar el worker el 19-09, y buena parte de los OOM.
        _thr.Thread(target=_bg_enrich, daemon=True).start()
    # `pending`: titulos sin poster TMDB para que el BOX (IP residencial) los
    # enriquezca y los empuje a /catenrich. El box ANTIGUO ignora este campo
    # (sigue funcionando con la semilla + el bg-enrich) -> backward-compatible.
    return jsonify({"ok": True, "items": len(raw), "bg": True, "pending": pending})


@app.post("/catenrich")
def catenrich():
    """El BOX enriquece con SU TMDB (IP residencial; Render lo tiene baneado) los
    titulos que /catfeed devolvio en `pending` y los empuja aqui:
        {kind, meta:{content_id: {poster, year, rating, overview, backdrop,
                                  genres, tmdb_id}}}
    Lo aplicamos por content_id a la cache del Inicio de ese kind (sin tocar TMDB
    desde Render) y lo acumulamos en la cache de enrich -> el Inicio sale en HD
    aunque la IP de Render este baneada por TMDB, y los proximos /catfeed se
    rellenan solos por content_id."""
    try:
        body = request.get_json(silent=True) or {}
    except Exception:
        body = {}
    kind = (body.get("kind") or "").strip().lower()
    meta = body.get("meta")
    if kind not in _CAT_BROWSE or not isinstance(meta, dict):
        return jsonify({"ok": False}), 400
    saved = _cat_enrich_store(meta)             # acumula (persistente)
    # Lo que quedo guardado MANDA: _cat_enrich_store rechaza que un box antiguo
    # pise un meta ya resuelto contra la ficha de DonTorrent, y aqui hay que
    # respetar la misma decision (si no, el rechazo valdria para el disco pero el
    # Inicio en memoria se quedaria igualmente con el poster equivocado).
    stored = _cat_enrich_load()
    key = "%s:1" % kind
    applied = 0
    with _FileLock(_CATBROWSE_FILE):            # RMW seguro de la cache del Inicio
        rec = _CATBROWSE_CACHE.get(key) or _catbrowse_load().get(key)
        if rec and rec.get("items"):
            for it in rec["items"]:
                cid = str(it.get("content_id"))
                m = meta.get(cid)
                sd = stored.get(cid) or {}
                if _meta_rango(sd) > _meta_rango(m):
                    m = sd
                if it.get("kind") == "serie" and _meta_rango(m) == 1:
                    continue        # serie con el emparejamiento de antes (dtbl59)
                if _cat_apply_meta(it, m):
                    applied += 1
            _CATBROWSE_CACHE[key] = rec
            try:
                disk = _catbrowse_load()
                disk[key] = rec
                _catbrowse_save(disk)
            except Exception:
                pass
    return jsonify({"ok": True, "saved": saved, "applied": applied})


_CAT_META_CACHE = {}


def _tmdb_detail(ep, tid):
    """runtime + trailer (YouTube) + nº temporadas de TMDB. Cacheado + breaker.
    {} si TMDB no responde (-> la ficha no muestra trailer/duracion, sin colgar)."""
    ck = (ep, str(tid))
    if ck in _CAT_META_CACHE:
        return _CAT_META_CACHE[ck]
    if _tmdb_is_down():
        return {}
    try:
        r = _TMDB_SESS.get(
            f"https://api.themoviedb.org/3/{ep}/{tid}",
            params={"api_key": _CAT_TMDB_KEY, "language": "es-ES",
                    "append_to_response": "videos"},
            timeout=(3, 5))
        if r.status_code != 200:
            _tmdb_mark(False)
            return {}
        d = r.json() or {}
        rt = d.get("runtime") or 0
        if not rt and d.get("episode_run_time"):
            rt = (d.get("episode_run_time") or [0])[0]
        vids = (d.get("videos") or {}).get("results") or []
        trailer = ""
        for v in vids:                       # trailer oficial primero
            if v.get("site") == "YouTube" and v.get("type") == "Trailer":
                trailer = v.get("key")
                break
        if not trailer:                       # si no, cualquier video de YouTube
            for v in vids:
                if v.get("site") == "YouTube":
                    trailer = v.get("key")
                    break
        out = {"runtime": rt, "trailer": trailer,
               "seasons": d.get("number_of_seasons") or 0}
        _tmdb_mark(True)
        _CAT_META_CACHE[ck] = out
        if len(_CAT_META_CACHE) > 2000:   # poda FIFO: no crecer sin limite
            for k in list(_CAT_META_CACHE)[:200]:
                _CAT_META_CACHE.pop(k, None)
        return out
    except Exception:
        _tmdb_mark(False)
        return {}


@app.get("/catmeta")
def catmeta():
    """Detalle PEREZOSO para la ficha enriquecida: duracion + trailer (YouTube).
    Una sola llamada TMDB POR FICHA ABIERTA (no por cuadricula), cacheada en
    memoria y protegida por el MISMO breaker del enrich -> si TMDB banea la IP,
    devuelve {} al instante y la ficha simplemente no muestra trailer/duracion
    (la sinopsis/generos/backdrop ya vienen gratis con el item). Cero baneo."""
    tid = (request.args.get("id") or "").strip()
    kind = (request.args.get("kind") or "movie").strip().lower()
    if not tid.isdigit():
        return jsonify({})
    ep = "tv" if kind in ("tv", "serie") else "movie"
    return jsonify(_tmdb_detail(ep, tid))


@app.get("/cattitlemeta")
def cattitlemeta():
    """Enriquece un item POR TITULO (para 'Mi lista': los favoritos guardados
    antes de la mejora no llevan sinopsis/generos/backdrop/tmdb_id). Resuelve TODO
    con el MISMO matching del catalogo (_cat_tmdb, cacheado) + detalle perezoso.
    Lo llama el front SOLO al abrir un favorito sin enriquecer (1 vez, luego se
    persiste en el movil) -> de uno en uno, cero rafagas, cero baneo."""
    title = (request.args.get("title") or "").strip()
    year = (request.args.get("year") or "").strip()
    kind = (request.args.get("kind") or "movie").strip().lower()
    if not title:
        return jsonify({})
    ep = "tv" if kind in ("tv", "serie") else "movie"
    # El año (si no esta ya en el titulo) afina el matching de titulos comunes
    # ("Perdida", "Venganza"...). _cat_tmdb lo extrae del propio string.
    q = title if (not year or year in title) else f"{title} {year}"
    meta = _bounded(lambda: _cat_tmdb(q, ep), 8.0, {}) or {}
    # SOLO los campos de la BUSQUEDA (1 llamada TMDB -> sinopsis/generos salen
    # rapido). El trailer/duracion los pide el front aparte via /catmeta(tmdb_id)
    # -> la ficha no espera al detalle para mostrar lo principal.
    return jsonify({"overview": meta.get("overview") or "",
                    "backdrop": meta.get("backdrop"),
                    "genres": meta.get("genres") or [],
                    "tmdb_id": meta.get("tmdb_id"),
                    "year": meta.get("year"),
                    "rating": meta.get("rating")})


@app.get("/catbrowse")
def catbrowse():
    kind = (request.args.get("kind") or "estrenos").strip().lower()
    try:
        page = max(1, int(request.args.get("page") or 1))
    except Exception:
        page = 1
    code = re.sub(r"\D", "", request.args.get("code", ""))[:6]
    key = f"{kind}:{page}"          # entrada DonTorrent (fuente PRINCIPAL = la web)
    dxkey = key + ":dx"             # entrada DivxTotal (ULTIMO recurso; NO pisa DT)
    now = _t.time()

    def _load(k, seed=False):
        # memoria -> disco -> (solo DT) SEMILLA del repo
        e = _CATBROWSE_CACHE.get(k)
        if not e:
            e = _catbrowse_load().get(k)
            if not e and seed:
                e = _catbrowse_seed().get(k)
            if e:
                _CATBROWSE_CACHE[k] = e
        return e

    def _store(k, rec):
        _CATBROWSE_CACHE[k] = rec
        try:
            disk = _catbrowse_load()
            disk[k] = rec
            _catbrowse_save(disk)
        except Exception:
            pass

    def _resp(items, **extra):
        """La respuesta del Inicio, con las otras fuentes DENTRO si ya estan.

        Antes iban en una peticion aparte que llegaba ~1 s despues, y el movil
        tenia que REORDENAR la cuadricula entera delante del usuario ("entro y
        un segundo despues parece que lo ordena"). Ahora, si la mezcla esta
        calculada -que es lo normal: dura 30 min y la refresca quien pasa por
        aqui- viaja en la MISMA respuesta y la portada se pinta una sola vez,
        ya en su orden definitivo. Si no lo esta, no se hace esperar a nadie:
        se calcula por detras y el front la pide aparte esta vez.
        Solo en la pagina 1: el scroll infinito de DonTorrent sigue igual."""
        out = {"items": _al_servir(items)}
        out.update(extra)
        # El estado de las fuentes, al dia (por detras, como mucho cada 5 min):
        # el aviso tiene que irse solo cuando vuelvan, no solo aparecer.
        for _s in ("wf", "et"):
            _fc_sondea(_s)
        _dt_caida_sondea()
        _con_caida(out)   # el Inicio lo avisa: sus titulos pueden no abrir
        _epsc_completa(out["items"])     # series con su lista completa (dtbl40)
        if page == 1 and request.args.get("mix") == "1":
            ent = _home_mix_cache(kind)
            if ent and ent.get("items"):
                out["mix"] = _al_servir(ent["items"])
                _epsc_completa(out["mix"])
            else:
                out["mix"] = []
                out["mixpend"] = True
                _home_mix_pronto(kind)
        return jsonify(out)

    dt_ent = _load(key, seed=True)
    # 0) SCROLL INFINITO (pagina 2 en adelante). Va lo PRIMERO a proposito: de
    #    la segunda pagina DonTorrent no tiene nada que dar (la pre-carga de las
    #    cajas solo trae la primera y Render no lo alcanza) y DivxTotal tarda
    #    -- medido en produccion: 14,3 s para acabar sirviendo WolfMax igual, y
    #    14 s mirando una pantalla quieta no es scroll infinito, es una espera.
    #    El indice local de WolfMax responde en milisegundos y tiene 5.000
    #    entradas. Si algun dia la caja precarga la pagina 2 de DonTorrent,
    #    `dt_ent` existira y mandara ella.
    if page > 1 and not dt_ent:
        try:
            salto = 12 + (page - 2) * 24        # lo que ya se vio antes
            mas = _wf_home_items(kind, 24, salto)
            if mas:
                for _it in mas:
                    if not _it.get("poster") and _it.get("thumb"):
                        _it["poster"] = _it["thumb"]
                # El enriquecimiento con TMDB es un EXTRA aqui: estas tarjetas
                # ya traen su caratula propia (el indice de WolfMax viaja con
                # ellas desde el addon 2.9.67). Asi que se le da un momento y
                # nada mas -- y si TMDB esta marcado caido, ni se intenta.
                # Con 6 s de tope, bajar al final del Inicio costaba 6,6 s
                # medidos en produccion, casi todo esperando a TMDB para no
                # mejorar ninguna imagen.
                if not _tmdb_is_down():
                    mas = _bounded(lambda: _cat_enrich(mas, limit=24), 1.5,
                                   default=mas) or mas
                return _resp(mas, src="wf", mas=True)
        except Exception:
            pass

    # 1) DonTorrent FRESCO en cache -> al instante, sin tocar ninguna fuente.
    if dt_ent and (now - dt_ent.get("ts", 0)) < _CATBROWSE_TTL:
        return _resp(dt_ent["items"], cached=True, src="dt")

    # 2) Intentar REFRESCAR DonTorrent (directo; el box solo si no hay stale).
    #    Tope CORTO (4s) si ya hay DT-stale: no hacemos esperar al usuario -> si
    #    Render esta baneado el breaker devuelve al instante y servimos el stale.
    #    Sin stale (1a vez, sin semilla) damos el presupuesto completo (8s) + box.
    bp = _CAT_BROWSE.get(kind, "/")
    path = bp if page <= 1 else (bp.rstrip("/") + f"/page/{page}")
    budget = 4.0 if dt_ent else 8.0
    html = _bounded(lambda: (_cat_dt_session_get(path) or ("", None))[0],
                    budget, "") or ""
    if not html and dt_ent and (now - dt_ent.get("ts", 0)) > 3600:
        # Una hora sin poder refrescar el Inicio: ¿es que DonTorrent esta
        # caido? Se mira por detras (no retrasa esta respuesta).
        _dt_caida_sondea()
    if not html and not dt_ent:
        # Inicio frio SIN nada DT que servir: marca el baneo (el slow-drip evade
        # el timeout de requests) para que el resto del Inicio salte DT al instante.
        # Con stale NO marcamos: el budget corto puede abortar a un DT solo lento.
        _dt_mark(False)
        if len(code) == 6 and not _dt_caida_ya():
            # Render bloqueado por DonTorrent -> traer el listado VIA EL BOX.
            job = "db" + os.urandom(5).hex()
            _kb_enqueue(code, {"c": "etjob", "job": job, "op": "dthtml",
                               "path": path})
            res = _catjob_wait(job, 9.0)
            html = (res or {}).get("html") or ""
            if _dt_es_mantenimiento(html):
                # su pagina de mantenimiento guardada como "el Inicio" lo
                # dejaria vacio
                _dt_caida_apunta(True, 503, "caja")
                html = ""
    if html:
        # TOPE DURO al enrich (ver /catetbox): `_cat_enrich` consulta TMDB, que
        # BANEA la IP de Render, y sin limite se queda colgado ocupando uno de
        # los 8 hilos de gunicorn. Esta es la ruta del INICIO, la que carga TODO
        # el mundo: unas pocas visitas con la cache vencida bastaban para dejar
        # el relay sordo (2026-08-07: el box no podia ni empujar /catfeed,
        # ReadTimeout de 45s, y las busquedas devolvian 0).
        items = _cat_parse_items(html)
        items = _bounded(lambda: _cat_enrich(items), 10.0, default=items)
        rec = {"items": items, "ts": now}
        _store(key, rec)
        return _resp(items, src="dt")

    # 3) DonTorrent no disponible AHORA -> servir DonTorrent STALE (de hace un
    #    rato) ANTES que DivxTotal. La web original es DonTorrent y los listados
    #    cambian despacio -> DT viejo >> DX fresco. (Pedido explicito del usuario.)
    if dt_ent:
        return _resp(dt_ent["items"], stale=True, src="dt")

    # 4) Nunca hubo DonTorrent (ni cache, ni disco, ni semilla) -> DivxTotal como
    #    ULTIMO recurso, en su PROPIA clave para no pisar nunca una entrada DT.
    dx_ent = _load(dxkey)
    if not (dx_ent and (now - dx_ent.get("ts", 0)) < _CATBROWSE_DX_TTL):
        dxit = _bounded(lambda: _dx_browse_items(kind, page), 6.0, []) or []
        if dxit:
            # mismo tope que arriba: TMDB no puede colgar un hilo del relay
            dx_ent = {"items": _bounded(lambda: _cat_enrich(dxit), 10.0,
                                        default=dxit),
                      "ts": now, "dx": True}
            _store(dxkey, dx_ent)
    if dx_ent:
        return _resp(dx_ent["items"], dx=True, src="dx")
    return jsonify({"items": []})


# ===========================================================================
# EL INICIO, CON LAS CUATRO FUENTES
# ===========================================================================
# El Inicio se llenaba SOLO de DonTorrent. Las otras tres se pedian a una caja
# (/catetbox op=latest), asi que con los Kodi apagados -que es lo normal cuando
# uno abre la web en el movil- no llegaba ninguna: EliteTorrent, DivxTotal y
# WolfMax no existian en la portada.
# Aqui se sirven SIN caja y sin tocar el camino de DonTorrent (que sigue dando
# la primera pantalla igual de rapido):
#   - WolfMax: del indice que ya vive en el relay. Sin red: los ids de sus URLs
#     crecen con el tiempo, asi que "lo ultimo" es ordenar por id.
#   - DivxTotal: directo, que a este si lo alcanza el relay (_dx_browse_items).
#   - EliteTorrent: necesita caja de verdad -> lo sigue trayendo boxMerge cuando
#     hay un Kodi despierto.
_CATMIX_CACHE = {}
_CATMIX_TTL = 1800          # 30 min: una portada no cambia cada minuto
# En DISCO ademas de en memoria, por dos razones que se ven en cuanto falla:
# los dos workers de gunicorn tienen cada uno su memoria (o sea que la portada
# se calculaba DOS veces y una persona veia una mezcla y otra otra), y ahora el
# vigilante releva workers mas a menudo -- sin esto, cada relevo dejaba el
# Inicio cojo hasta que alguien pagara el recalculo.
_CATMIX_FILE = "/tmp/mw_cathomemix.json"
_CATMIX_BG = {}             # kind -> cuando se lanzo su calculo de fondo


def _catmix_save():
    try:
        tmp = _CATMIX_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            _json.dump(_CATMIX_CACHE, f)
        os.replace(tmp, _CATMIX_FILE)
    except Exception:
        pass


def _home_mix_cache(kind):
    """La mezcla ya calculada y FRESCA, de memoria o de disco. None si no hay."""
    now = _t.time()
    ent = _CATMIX_CACHE.get(kind)
    if not ent:
        try:
            with open(_CATMIX_FILE, "r", encoding="utf-8") as f:
                d = _json.load(f) or {}
            ent = d.get(kind)
            if ent:
                _CATMIX_CACHE[kind] = ent
        except Exception:
            ent = None
    if ent and (now - ent.get("ts", 0)) < ent.get("ttl", _CATMIX_TTL):
        return ent
    return None


def _home_mix_pronto(kind):
    """Calcula la mezcla POR DETRAS para que la proxima visita la tenga ya.

    Sin esperar a nadie y una sola vez: si dos personas abren la app a la vez
    con la cache fria, no se lanzan dos calculos iguales (que ademas tocan
    DivxTotal y TMDB, o sea a quien nos banea)."""
    now = _t.time()
    with _ENR_LOCK:
        if (now - _CATMIX_BG.get(kind, 0.0)) < 60.0:
            return
        _CATMIX_BG[kind] = now

    def _ir():
        try:
            _home_mix(kind)
        except Exception:
            pass
    try:
        _thr.Thread(target=_ir, daemon=True).start()
    except Exception:
        pass


def _intercala(base, extra, cada=2):
    """Reparte `extra` dentro de `base`: dos de la principal por cada una de
    las demas. DonTorrent trae 25-33 y las otras 12 entre las dos, asi que
    ponerlas al final es condenarlas a no verse nunca; y alternarlas aqui -en
    el servidor, con todo delante- es lo que evita que el movil tenga que
    reordenar la pantalla a mitad de carga."""
    out, i, j = [], 0, 0
    while i < len(base) or j < len(extra):
        for _n in range(cada):
            if i < len(base):
                out.append(base[i])
                i += 1
        if j < len(extra):
            out.append(extra[j])
            j += 1
    return out


def _zip_largo(a, b):
    """Como zip pero sin tirar la cola de la lista mas larga."""
    for i in range(max(len(a), len(b))):
        yield (a[i] if i < len(a) else None, b[i] if i < len(b) else None)


# --- LO ULTIMO DE WOLFMAX, DE WOLFMAX (dtbl52) ----------------------------------
# El Inicio sacaba lo de WolfMax del INDICE, ordenado por el numero de la URL.
# Con la web nueva los ids son letras y numeros al azar ("7vwh4v"): ese orden ya
# no significaba nada, y el indice solo tiene lo que se ha buscado estos dias
# (asi salio "El Dorado" de 1966 en Estrenos: alguien lo busco). Ahora una caja
# trae lo ultimo de WolfMax -- /peliculas (3 paginas) y /series -- como mucho
# cada 30 min y SOLO cuando alguien abre el Inicio (con todo apagado, nada).
# Estrenos: solo pelis de este año o del anterior. Si aun no hay nada (recien
# desplegado), el indice de siempre, y la portada se guarda poco rato.
_WFULT_FILE = "/tmp/mw_wf_ultimos.json"
_WFULT = {}                  # clase ("movie"/"tvshow") -> {"items": [...], "ts": t}
_WFULT_VUELO = {}            # clase -> desde cuando hay una peticion en marcha
_WFULT_DIAG = {}             # clase -> el ultimo intento: {ts, n, cajas, por} (dtbl72)
_WFULT_CADA = 30 * 60
_WFULT_PAGINAS = {"movie": (1, 2, 3), "tvshow": (1, 2)}
_WFULT_MIN = {"movie": None, "tvshow": (2, 9, 80)}    # "kind" en op=latest: 2.9.80
_WF_RANGO = {"4K": 9, "1080p": 8, "BDRemux": 8, "720p": 6, "BluRay": 6,
             "MicroHD": 5, "WEB-DL": 5, "480p": 4, "HDTV": 3, "HDRip": 3,
             "WEBRip": 3, "DVDRip": 2, "DVD": 2}


_WFULT_MT = [0.0]            # mtime del fichero la ultima vez que se leyo


def _wfult_disco():
    try:
        with open(_WFULT_FILE, "r", encoding="utf-8") as f:
            return _json.load(f) or {}
    except Exception:
        return {}


def _wfult_lee(clase):
    # Cada worker tiene su copia en memoria; si el OTRO la renovo (fichero
    # mas nuevo), se coge la suya en vez de seguir con la vieja (dtbl72).
    try:
        mt = os.path.getmtime(_WFULT_FILE)
    except Exception:
        mt = 0.0
    if mt and (mt != _WFULT_MT[0] or not _WFULT.get(clase)):
        _WFULT_MT[0] = mt
        for k, v in _wfult_disco().items():
            if isinstance(v, dict) and float(v.get("ts") or 0) > \
                    float((_WFULT.get(k) or {}).get("ts") or 0):
                _WFULT[k] = v
    return _WFULT.get(clase) or {}


def _wfult_guarda():
    """A disco, FUNDIENDO con lo que haya: se escribia la memoria de este worker
    tal cual y, si no tenia una clase, borraba la que el otro habia guardado."""
    try:
        d = _wfult_disco()
        for k, v in _WFULT.items():
            if isinstance(v, dict) and float(v.get("ts") or 0) >= \
                    float((d.get(k) or {}).get("ts") or 0):
                d[k] = v
        tmp = "%s.%d.tmp" % (_WFULT_FILE, os.getpid())
        with open(tmp, "w", encoding="utf-8") as f:
            _json.dump(d, f)
        os.replace(tmp, _WFULT_FILE)
    except Exception:
        pass


def _wfult_trae(clase):
    """Una caja trae lo ultimo de WolfMax de esa clase. Lista de items.

    Si la primera no trae NI la primera pagina (no contesta, o su casa no llega
    a WolfMax), se le pide a OTRA: era un solo camino y, con la misma caja
    elegida siempre la primera, el Inicio podia quedarse horas con la foto
    vieja sin que nada lo dijera (dtbl72). Lo que paso queda en _WFULT_DIAG."""
    _min = _WFULT_MIN.get(clase)
    box = _box_wf("", minimo=_min)
    if not box:
        _WFULT_DIAG[clase] = {"ts": int(_t.time()), "n": 0, "por": "sin caja al dia"}
        return []
    items, probadas, por = [], [], ""
    while box and len(probadas) < 2:
        probadas.append(box)
        for pag in _WFULT_PAGINAS.get(clase, (1,)):
            j = "wl" + os.urandom(5).hex()
            _kb_enqueue(box, {"c": "etjob", "job": j, "op": "latest", "srcs": "wf",
                              "kind": clase, "page": pag})
            res = _catjob_wait(j, 30.0)
            if res is None and pag == 1:
                por = "la caja no contesto"
            its = [x for x in ((res or {}).get("items") or [])
                   if (x or {}).get("source") == "wf" and _wf_url_nueva(x.get("url"))
                   and ((x.get("kind") == "serie") == (clase == "tvshow"))]
            if not its:
                if pag == 1 and res is not None:
                    por = "vacio"
                break
            items += its
        if items:
            break
        box = _box_wf("", excluir=tuple(probadas), minimo=_min)
    _WFULT_DIAG[clase] = {"ts": int(_t.time()), "n": len(items), "cajas": len(probadas),
                          "por": "" if items else (por or "vacio")}
    return items


def _wfult_refresca(clase, forzar=False):
    """Por detras: como mucho cada 30 min y una a la vez por clase."""
    now = _t.time()
    if not forzar and (now - float(_wfult_lee(clase).get("ts") or 0)) < _WFULT_CADA:
        return
    if (now - _WFULT_VUELO.get(clase, 0.0)) < 150:
        return
    _WFULT_VUELO[clase] = now

    def _ir():
        try:
            items = _wfult_trae(clase)
            if items:
                _WFULT[clase] = {"items": items, "ts": _t.time()}
                _wfult_guarda()
                _wfidx_learn(items)
        except Exception:
            pass
        finally:
            _WFULT_VUELO[clase] = 0.0
    try:
        _thr.Thread(target=_ir, daemon=True).start()
    except Exception:
        _WFULT_VUELO[clase] = 0.0


def _wfult_tarjetas(kind):
    """Las tarjetas del Inicio desde lo ultimo de WolfMax, o None si aun no hay."""
    clase = "tvshow" if kind == "series" else "movie"
    e = _wfult_lee(clase)
    _wfult_refresca(clase)
    crudos = e.get("items") or []
    if not crudos:
        return None
    items = []
    for x in crudos:
        it = dict(x)
        it["thumb"] = _img_cdn(it.get("thumb") or "")
        disp, ql = _cat_clean_quality(it.get("title", ""))
        it["title"] = disp
        it["quality"] = it.get("quality") or ql
        items.append(it)
    if kind == "estrenos":
        # "Estrenos" es de ESTE año o del anterior: WolfMax sube tambien clasicos
        _anio = _t.localtime().tm_year
        items = [it for it in items if int(it.get("year") or 0) >= _anio - 1]
    items = _wf_colapsa(_cat_group_episodes(items))
    # una tarjeta por titulo (+año), la MEJOR version: el 4K manda
    mejor, orden = {}, []
    for it in items:
        k = (_wf_norm(it.get("title") or ""), it.get("year") or "")
        if not k[0]:
            continue
        if k not in mejor:
            mejor[k] = it
            orden.append(k)
        elif _WF_RANGO.get(it.get("quality") or "", 1) > \
                _WF_RANGO.get(mejor[k].get("quality") or "", 1):
            mejor[k] = it
    return [mejor[k] for k in orden]


def _wf_home_items(kind, limit=12, salto=0):
    ult = _wfult_tarjetas(kind)
    if ult is not None:
        return ult[salto:salto + limit]
    return _wf_home_items_indice(kind, limit, salto)


def _wf_home_items_indice(kind, limit=12, salto=0):
    """Lo ultimo de WolfMax segun el indice local. Cero red, milisegundos.

    `salto` deja pasar las primeras N tarjetas ya vistas: es lo que permite que
    el scroll infinito del Inicio siga dando contenido cuando DonTorrent no
    tiene mas paginas que ofrecer.

    NUNCA para Estrenos: el indice no sabe el año (es lo ultimo que se ha
    BUSCADO, no lo ultimo que se ha publicado). Tras un despliegue, Estrenos
    enseñaba "Matrix" (1999) y "El Padrino" porque alguien las acababa de
    buscar (dtbl64). Mejor ningun WolfMax unos minutos que eso."""
    if kind == "estrenos":
        return []
    idx = _wfidx_load()
    if not idx:
        return []
    orden = []
    for url, e in idx.items():
        if not isinstance(e, dict):
            continue
        t = e.get("t") or ""
        k = e.get("k") or ""
        if not t or _wf_pobre(url, t, k):
            continue
        es_serie = k.startswith("tvshow")
        if kind == "series" and not es_serie:
            continue
        if kind == "peliculas" and es_serie:
            continue
        m = None if _wf_url_nueva(url) else _re_dt.search(r"/(\d+)(?:/|$)", url)
        orden.append((int(m.group(1)) if m else len(orden), url, e))
    orden.sort(key=lambda x: -x[0])
    items = []
    for _id, url, e in orden[salto:salto + limit * 6]:  # margen: muchos repiten
        _im = e.get("i") or ""
        items.append({
            "title": e.get("t") or "",
            "kind": "serie" if (e.get("k") or "").startswith("tvshow") else "movie",
            "source": "wf", "url": url, "content_id": url,
            "thumb": _img_cdn(_im),
            "quality": e.get("q") or _wf_quality_from_url(url), "tabla": "wf"})
    # el mismo aseo que en la busqueda: quitar la calidad del titulo y juntar
    # los capitulos de una misma serie en UNA tarjeta.
    for it in items:
        disp, ql = _cat_clean_quality(it.get("title", ""))
        it["title"] = disp
        if not it.get("quality"):
            it["quality"] = ql or _wf_quality_from_url(it.get("url"))
    items = _wf_colapsa(_cat_group_episodes(items))
    vistos, unicos = set(), []
    for it in items:
        # "Ted Lasso Temporada Temporada [ 4 ] Capitulo [ 6 ]" no es nombre para
        # una tarjeta: en una portada va la SERIE, no el capitulo suelto.
        if _WF_CAP_RE.search(it.get("title") or ""):
            _n = _cat_clean_title(it.get("title") or "").strip(" -.:")
            if _n:
                it["title"] = _n
        # WolfMax publica una entrada por calidad -> el mismo titulo salia tres
        # veces seguidas. Se queda la primera, que es la mas reciente.
        k = _wf_norm(it.get("title") or "")
        if not k or k in vistos:
            continue
        vistos.add(k)
        unicos.append(it)
    return unicos[:limit]


@app.get("/cathomemix")
def cathomemix():
    """Lo que el Inicio anade a DonTorrent, cuando hay que pedirlo aparte.

    En el caso normal ya no se usa: /catbrowse lo sirve TODO junto y en su
    orden definitivo (ver _home_mix_cache). Esto queda para cuando la mezcla
    todavia no estaba calculada -- entonces el front la pide aqui y las
    tarjetas se anaden AL FINAL, sin mover ni una de las que ya se ven."""
    kind = (request.args.get("kind") or "estrenos").strip().lower()
    d = dict(_home_mix(kind))
    # por el mismo sitio que todo lo demas: si no, esta via (la de cuando la
    # mezcla aun no estaba calculada) servia los titulos con el "(2026)" pegado
    d["items"] = _al_servir(list(d.get("items") or []))
    return jsonify(d)


def _home_mix(kind):
    now = _t.time()
    ent = _home_mix_cache(kind)
    if ent:
        return {"items": ent["items"], "cached": True}
    wf, dx = [], []
    try:
        wf = _wf_home_items(kind, 12)
    except Exception:
        pass
    # DivxTotal con presupuesto corto: si tarda, el Inicio se queda como estaba
    # (con DonTorrent y WolfMax) en vez de hacer esperar a nadie.
    try:
        dx = (_bounded(lambda: _dx_browse_items(kind, 1), 6.0, []) or [])[:12]
    except Exception:
        pass
    # Uno de cada, no doce de una y luego doce de la otra: asi las dos asoman
    # arriba en vez de quedar una sepultada bajo la otra.
    items = []
    for a, b in _zip_largo(wf, dx):
        if a is not None:
            items.append(a)
        if b is not None:
            items.append(b)
    if not items:
        return {"items": []}
    # Mismo tope que el resto del Inicio: TMDB banea la IP de Render y no puede
    # quedarse colgado ocupando uno de los 12 hilos.
    # La caratula PROPIA, ya puesta: si TMDB casa el titulo la mejorara, pero si
    # el enrich no llega a tiempo (tope de 10 s) el item salia con `thumb` y sin
    # `poster`... y la tarjeta pinta `poster`. Resultado: WolfMax en gris en la
    # portada aunque tuvieramos su imagen. Nunca dejar un item sin poster
    # teniendo con que.
    for _it in items:
        if not _it.get("poster") and _it.get("thumb"):
            _it["poster"] = _it["thumb"]
    items = _bounded(lambda: _cat_enrich(items, limit=24), 10.0,
                     default=items) or items
    for _it in items:
        if not _it.get("poster") and _it.get("thumb"):
            _it["poster"] = _it["thumb"]
    # Si una fuente no contesto, NO guardamos media hora una portada coja: se
    # reintenta en 3 min. Media hora sin DivxTotal por un tropiezo de 6 s es
    # justo el fallo que no se ve -- la portada parece normal, solo que le
    # falta una fuente entera.
    # Media portada en gris tampoco se guarda media hora (ver arriba).
    _grises = sum(1 for _it in items if not _it.get("poster"))
    _ok = bool(wf and dx) and _grises <= max(2, len(items) // 6) and \
        bool(_wfult_lee("tvshow" if kind == "series" else "movie").get("items"))
    _CATMIX_CACHE[kind] = {"items": items, "ts": now,
                           "ttl": _CATMIX_TTL if _ok else 180}
    _catmix_save()
    return {"items": items}


@app.get("/catdump")
def catdump():
    """Vuelca la cache ACTUAL de DonTorrent (claves kind:1) en formato semilla.
    Se usa para regenerar catalog_seed.json tras un /catfeed bueno: capturar este
    JSON y commitearlo al repo. NO toca ninguna fuente (solo lee cache/disco)."""
    out = {}
    src = dict(_catbrowse_load())
    for k, v in _CATBROWSE_CACHE.items():
        src[k] = v
    for k, v in src.items():
        # solo entradas DonTorrent de 1a pagina, con items (lo que siembra el Inicio)
        if k.endswith(":1") and not (v or {}).get("dx") and (v or {}).get("items"):
            out[k] = {"items": v["items"], "ts": v.get("ts", 0)}
    return jsonify(out)


# --- Uso de la app, SOLO PARA EL DUEÑO (dtbl81) ------------------------------
# "¿Cuántas teles hay ahora? ¿La gente la usa?" -- y que el resto no lo sepa.
# Hasta dtbl80 esos recuentos salían en /catdiag, que es pública; ahora van
# detrás de una LLAVE y aquí se lleva además un histórico por día.
#  * Nada de códigos: cada caja se cuenta por una huella HMAC con el secreto de
#    Render (MW_KV_FIRMA), recortada. Un código de 6 cifras a pelo, o con un
#    sha256 sin secreto, se saca por fuerza bruta en un segundo.
#  * Una muestra por minuto entre los dos workers (cerrojo + marca en el fichero).
#  * El histórico se copia a mw-sync (/kv/uso) CIFRADO: las lecturas de mw-sync
#    son públicas y el repo dice dónde están. /tmp se vacía en cada despliegue.
#  * La llave: la reclama UNA VEZ quien llega primero en los 20 primeros minutos
#    tras arrancar, solo si la copia se pudo leer y no hay ninguna. Se guarda su
#    sha256 (la llave son 144 bits al azar). Para cambiarla: borrar `kv:uso` de
#    la D1 de mw-sync (o rotar MW_KV_FIRMA) y reclamar otra tras desplegar.
_USO_FILE = "/tmp/mw_uso.json"
_USO_SYNC = "https://mw-sync.israeldm93.workers.dev/kv/uso"
_USO_T0 = _t.time()
_USO_DIAS = 400                 # días que se guardan (compactos: ~100 B cada uno)
_USO_SETS_DIAS = 2              # hoy y ayer guardan las huellas; los demás, cuentas
_USO_ALTA_S = 20 * 60
_USO_CAB = set()                # qué cabeceras de origen trae Render (sin valores)
_USO_NUBE = {"leida": False, "bajadas": 0, "subidas": 0, "fallos": 0,
             "vuelo": 0.0, "subida_ts": 0.0, "cambios": 0}
_USO_SAL = {"local": os.urandom(16)}   # sin secreto (en el PC): huellas de un solo proceso


def _uso_es(ts=None):
    """(día 'AAAA-MM-DD', hora 0-23, 'HH:MM') en hora de España."""
    import datetime as _dtm
    ts = _t.time() if ts is None else float(ts)
    try:
        from zoneinfo import ZoneInfo
        d = _dtm.datetime.fromtimestamp(ts, ZoneInfo("Europe/Madrid"))
    except Exception:
        # sin tzdata: horario de verano de la UE (último domingo de marzo y de
        # octubre, a la 01:00 UTC)
        u = _dtm.datetime.utcfromtimestamp(ts)

        def _ult_dom(mes):
            d0 = _dtm.datetime(u.year, mes, 31, 1, 0)
            return d0 - _dtm.timedelta(days=(d0.weekday() + 1) % 7)
        verano = _ult_dom(3) <= u < _ult_dom(10)
        d = u + _dtm.timedelta(hours=2 if verano else 1)
    return d.strftime("%Y-%m-%d"), d.hour, d.strftime("%H:%M")


def _uso_huella(code):
    sem = _kv_par()[0] or _USO_SAL["local"]
    import hmac as _hm
    return _hm.new(sem, b"mw-uso-caja-v1\n" + str(code).encode("utf-8"),
                   _hl.sha256).hexdigest()[:12]


# huellas que se guardan por día: Kodis encendidos (c), con algo puesto (r),
# con la web mirándolos (m) y conexiones (ip: la de casa, cifrada) (dtbl104)
_USO_SETS = ("c", "r", "m", "ip", "du")    # du: códigos que usan varias teles a la vez
_USO_CORTO_MIN = 15             # encendido menos que esto en el día: "solo un rato"
# Diccionarios de cada día (dtbl104-106). forma: n = clave -> número;
# s = clave -> texto corto; p = clave -> [a, b]; b = clave -> 5 números;
# l = clave -> lista de huellas cortas. Ninguno guarda un código ni una IP.
#   km/rm: minutos encendido / viendo de cada Kodi (hoy y ayer)
#   rf/rq/rk: lo mandado desde la web, por fuente, calidad y película/serie
#   ok/ko/cb: envíos que arrancan, que no y que se cambian antes, por fuente
#   ta/tb: segundos hasta arrancar (suma, n) y su reparto, por fuente
#   pm: reproducciones que empiezan, desde la web o con el mando
#   rs: minutos vistos por resolución real; bf: [min cargando, min viendo]
#   dv/pa: aparato y país de cada Kodi (hoy y ayer) -> dvn/kvn/pan, cuentas
#   vt: lo que se pone (título sin capítulo) -> huellas de Kodi; vtn, cuentas
#   bq: búsquedas -> [veces, veces sin nada]
#   vq/vqv: (dtbl134) minutos vistos / vídeos empezados en el propio móvil, por servidor
_USO_DIC = {"km": ("n", 5000), "rm": ("n", 5000), "rf": ("n", 20), "rq": ("n", 20),
            "rk": ("n", 4), "ok": ("n", 20), "ko": ("n", 20), "cb": ("n", 20),
            "ta": ("p", 20), "tb": ("b", 20), "pm": ("n", 4), "rs": ("n", 8),
            "bf": ("p", 20), "dv": ("s", 5000), "pa": ("s", 5000), "dvn": ("n", 40),
            "kvn": ("n", 40), "pan": ("n", 80), "vt": ("l", 400), "vtn": ("n", 400),
            "bq": ("p", 400), "lim": ("n", 60), "vm": ("n", 400), "ki": ("s", 5000),
            "vq": ("n", 20), "vqv": ("n", 20)}
_USO_BQ_DIAS = 35               # las búsquedas se guardan 5 semanas
_USO_TT = (15, 30, 60, 120)     # cortes de "segundos hasta arrancar"
_USO_DIA_ARRANQUE = "2026-11-02"   # el detalle (casas, fuentes, servicio...) se midió desde la tarde


def _uso_clave_ok(k):
    return isinstance(k, str) and 0 < len(k) <= 60 and not re.search(r"[\x00-\x1f<>]", k)


def _uso_dic_valida(x, forma, tope):
    out = {}
    for k, v in list(x.items())[:tope]:
        if not _uso_clave_ok(k):
            continue
        try:
            if forma == "n":
                out[k] = max(0, int(v))
            elif forma == "s":
                out[k] = str(v)[:24]
            elif forma == "p":
                out[k] = [max(0, int(v[0])), max(0, int(v[1]))]
            elif forma == "b":
                out[k] = [max(0, int(z)) for z in list(v)[:5]] + [0] * max(0, 5 - len(list(v)[:5]))
            elif forma == "l":
                out[k] = sorted({str(z)[:6] for z in v if isinstance(z, str)})[:2000]
        except Exception:
            continue
    return out


def _uso_dic_funde(forma, xa, xb):
    out = {}
    for k in set(xa) | set(xb):
        a, b = xa.get(k), xb.get(k)
        if a is None or b is None:
            out[k] = a if b is None else b
        elif forma == "n":
            out[k] = max(a, b)
        elif forma in ("p", "b"):
            out[k] = [max(y, z) for y, z in zip(a, b)]
        elif forma == "l":
            out[k] = sorted(set(a) | set(b))
        else:
            out[k] = b
    return out


def _uso_vacio():
    return {"v": 1, "adm": "", "dias": {}, "cj": {}, "act": {}, "desde": _uso_es()[0], "ult": 0}


def _uso_valida(d):
    """Lo que venga de disco o de la copia, con la forma buena (o vacío)."""
    out = _uso_vacio()
    if not isinstance(d, dict):
        return out
    adm = str(d.get("adm") or "")
    out["adm"] = adm if re.match(r"^[0-9a-f]{64}$", adm) else ""
    if re.match(r"^\d{4}-\d\d-\d\d$", str(d.get("desde") or "")):
        out["desde"] = d["desde"]
    try:
        out["ult"] = float(d.get("ult") or 0)
    except Exception:
        pass
    for dia, e in (d.get("dias") or {}).items() if isinstance(d.get("dias"), dict) else []:
        if not (re.match(r"^\d{4}-\d\d-\d\d$", str(dia)) and isinstance(e, dict)):
            continue
        x = {}
        for k in _USO_SETS:
            if isinstance(e.get(k), list):
                x[k] = sorted({str(h)[:12] for h in e[k] if isinstance(h, str)})
        for k, (forma, tope) in _USO_DIC.items():
            if isinstance(e.get(k), dict):
                x[k] = _uso_dic_valida(e[k], forma, tope)
        for k in ("nc", "nr", "nm", "nip", "ndu", "nk15", "pico", "tm", "mu"):
            try:
                x[k] = max(0, int(e.get(k) or 0))
            except Exception:
                x[k] = 0
        x["pico_h"] = str(e.get("pico_h") or "")[:5]
        hp = e.get("hp") if isinstance(e.get("hp"), list) else []
        x["hp"] = [max(0, int(v or 0)) if isinstance(v, (int, float)) else 0 for v in hp[:24]] + \
            [0] * max(0, 24 - len(hp[:24]))
        out["dias"][dia] = x
    if isinstance(d.get("cj"), dict):
        for h, v in d["cj"].items():
            if isinstance(v, list) and len(v) == 2 and all(isinstance(z, str) for z in v):
                out["cj"][str(h)[:12]] = [v[0][:10], v[1][:10]]
    if isinstance(d.get("act"), dict):
        for h, v in list(d["act"].items())[:5000]:
            if isinstance(v, list):
                ds = sorted({int(z) for z in v if isinstance(z, int) and 700000 < z < 800000})
                if ds:
                    out["act"][str(h)[:12]] = ds[-60:]
    return out


def _uso_lee():
    try:
        with open(_USO_FILE, "r", encoding="utf-8") as f:
            return _uso_valida(_json.load(f))
    except Exception:
        return _uso_vacio()


def _uso_guarda(d):
    try:
        tmp = "%s.%d.tmp" % (_USO_FILE, os.getpid())
        with open(tmp, "w", encoding="utf-8") as f:
            _json.dump(d, f)
        os.replace(tmp, _USO_FILE)
    except Exception:
        pass


def _uso_cuenta(e, k):
    """Cuántas cajas: la lista si aún la hay, si no la cuenta ya compactada."""
    return len(e[k]) if isinstance(e.get(k), list) else int(e.get("n" + k) or 0)


def _uso_compacta(d, hoy):
    """Hoy y ayer guardan sus huellas (para no contar dos veces a nadie al
    fundir con la copia); los días anteriores, solo las cuentas."""
    import datetime as _dtm
    dias = sorted(d["dias"])
    try:
        base = _dtm.date.fromisoformat(hoy)
        guarda = {(base - _dtm.timedelta(days=i)).isoformat() for i in range(_USO_SETS_DIAS)}
    except Exception:
        guarda = {hoy}
    for dia in dias:
        e = d["dias"][dia]
        if dia not in guarda:
            for k in _USO_SETS:
                if isinstance(e.get(k), list):
                    e["n" + k] = max(int(e.get("n" + k) or 0), len(e[k]))
                    e.pop(k, None)
            if isinstance(e.get("km"), dict):
                e["nk15"] = max(int(e.get("nk15") or 0), _uso_cortos(e))
                e.pop("km", None)
            e.pop("rm", None)
            if isinstance(e.get("dv"), dict):
                dvn, kvn = {}, {}
                for v in e["dv"].values():
                    pl, kv = (str(v).split("|") + ["", ""])[:2]
                    dvn[pl or "?"] = dvn.get(pl or "?", 0) + 1
                    kvn[kv or "?"] = kvn.get(kv or "?", 0) + 1
                e["dvn"], e["kvn"] = dvn, kvn
                e.pop("dv", None)
            if isinstance(e.get("pa"), dict):
                pan = {}
                for v in e["pa"].values():
                    pan[v] = pan.get(v, 0) + 1
                e["pan"] = pan
                e.pop("pa", None)
            if isinstance(e.get("vt"), dict):
                e["vtn"] = {t: len(hs) for t, hs in e["vt"].items()}
                e.pop("vt", None)
            e.pop("ki", None)
        try:
            if (base - _dtm.date.fromisoformat(dia)).days > _USO_BQ_DIAS:
                e.pop("bq", None)
        except Exception:
            pass
    for dia in dias[:-_USO_DIAS]:
        d["dias"].pop(dia, None)
    if len(d["act"]) > 5000:
        for h in sorted(d["act"], key=lambda h: d["act"][h][-1])[:len(d["act"]) - 5000]:
            d["act"].pop(h, None)
    if len(d["cj"]) > 5000:      # nunca debería: 5000 Kodis distintos
        for h in sorted(d["cj"], key=lambda h: d["cj"][h][1])[:len(d["cj"]) - 5000]:
            d["cj"].pop(h, None)


def _uso_cortos(e):
    """Kodis que ese día estuvieron encendidos solo un rato (< _USO_CORTO_MIN)."""
    if isinstance(e.get("km"), dict):
        return sum(1 for v in e["km"].values() if v < _USO_CORTO_MIN)
    return int(e.get("nk15") or 0)


def _uso_res(dg):
    """'1,920x1,080' -> '1080' (lo que de verdad se ve, no la etiqueta).
    (dtbl117) Kodi manda los números CON separador de miles ("1,920x1,080",
    "3,840x1,600"): antes no se leían y solo contaban los de 720p. Y se mira el
    ANCHO: una peli panorámica en 1080p mide 1920x800, no 1080 de alto."""
    try:
        w = int(re.sub(r"\D", "", str((dg or {}).get("res") or "").split("x")[0]))
    except Exception:
        return ""
    return "" if w <= 0 else "2160" if w >= 3000 else "1080" if w >= 1700 else "720" if w >= 1200 else "sd"


_USO_ORDENES = {"desde": 0}     # (dtbl116) órdenes de la web recibidas por este worker
_USO_MOVIL_S = 180              # un vídeo que empieza hasta 3 min después de tocar el mando del móvil


def _uso_toque_movil(code):
    """(dtbl114) Se ha tocado algo en el mando del móvil (la lista espejo de la
    tele, OK o una búsqueda): si en 3 min empieza un vídeo, lo eligió el móvil."""
    try:
        now = _t.time()
        with _FileLock(_USO_PEND_FILE):
            pend = _uso_pend_lee()
            pend["w:" + code] = {"ts": now}
            _uso_pend_guarda(pend, now)
    except Exception:
        pass


def _uso_resuelve_ok(e, x, sg):
    """Un envío de la web que arrancó a los `sg` segundos."""
    f = x.get("f") or "otra"
    _uso_suma(e, "pm", "web")
    _uso_suma(e, "ok", f)
    ta = e.setdefault("ta", {}).setdefault(f, [0, 0])
    ta[0] += sg
    ta[1] += 1
    tb = e.setdefault("tb", {}).setdefault(f, [0, 0, 0, 0, 0])
    tb[sum(1 for c in _USO_TT if sg >= c)] += 1


def _uso_muestra_mas(d, e, st, vivas, rep, now, hoy, np=None):
    """(dtbl106) aparato, país, resolución real, cargas y quién vuelve."""
    import datetime as _dtm
    try:
        dia_n = _dtm.date.fromisoformat(hoy).toordinal()
    except Exception:
        dia_n = 0
    pend = _uso_pend_lee()
    for c in vivas:
        h = _uso_huella(c)
        ent = st.get(c) or {}
        dev = ent.get("dev") or {}
        if dev.get("pl"):
            e.setdefault("dv", {})[h] = ("%s|%s" % (dev.get("pl", ""), dev.get("kv", "")))[:24]
        if ent.get("pais"):
            e.setdefault("pa", {})[h] = ent["pais"]
        if ent.get("ih"):         # (dtbl116) para la auditoría: Kodi -> conexión (huellas)
            e.setdefault("ki", {})[h] = str(ent["ih"])[:12]
        if dia_n:
            ds = d["act"].get(h) or []
            if not ds:          # los de antes: su primer y último día ya sabidos
                for z in d["cj"].get(h) or []:
                    try:
                        ds.append(_dtm.date.fromisoformat(z).toordinal())
                    except Exception:
                        pass
            if dia_n not in ds:
                ds.append(dia_n)
            d["act"][h] = sorted(set(ds))[-60:]
    # (dtbl112) lo que de verdad se ve en cada tele: teles distintas por título
    # y minutos. Antes solo contaba lo mandado desde la web.
    for c in rep:
        t = _uso_titulo(((np or {}).get(c) or {}).get("title"))
        if t:
            vt = e.setdefault("vt", {})
            if t in vt or len(vt) < 400:
                vt[t] = sorted(set(vt.get(t) or []) | {_uso_huella(c)[:6]})
                _uso_suma(e, "vm", t)
    for c in rep:
        dg = (st.get(c) or {}).get("diag") or {}
        r = _uso_res(dg)
        if r:
            _uso_suma(e, "rs", r)
        f = (pend.get(c) or {}).get("f") or "tele"     # sin envío de la web: puesto en la tele
        bf = e.setdefault("bf", {}).setdefault(f, [0, 0])
        bf[1] += 1
        if str(dg.get("cach") or "") == "1":
            bf[0] += 1
    # (dtbl111) un envío sin resolver cuya tele YA está reproduciendo algo que
    # empezó después del envío (minuto del vídeo): arrancó. Pasa al re-enviar el
    # mismo capítulo, cuyo título ya se conocía y no "es nuevo".
    resueltos = []
    for c, x in pend.items():
        if c[:2] in ("t:", "w:") or x.get("hecho") or c not in (np or {}):
            continue
        try:
            inicio = now - int((np[c] or {}).get("elapsed") or 0)
        except Exception:
            continue
        if inicio >= float(x.get("ts") or 0) - 15:
            resueltos.append((c, max(0, int(inicio - float(x.get("ts") or 0)))))
    if resueltos:
        with _FileLock(_USO_PEND_FILE):
            pend = _uso_pend_lee()
            for c, sg in resueltos:
                x = pend.get(c)
                if x and not x.get("hecho"):
                    x["hecho"] = "ok"
                    _uso_resuelve_ok(e, x, sg)
            _uso_pend_guarda(pend, now)
    # los envíos que no han arrancado a tiempo: "no arrancó"
    caducados = [c for c, x in pend.items()
                 if c[:2] not in ("t:", "w:") and not x.get("hecho") and (now - float(x.get("ts") or 0)) > _USO_PEND_S]
    if caducados:
        with _FileLock(_USO_PEND_FILE):
            pend = _uso_pend_lee()
            for c in caducados:
                x = pend.get(c)
                if x and not x.get("hecho") and (now - float(x.get("ts") or 0)) > _USO_PEND_S:
                    _uso_suma(e, "ko", x.get("f") or "otra")
                    x["hecho"] = "ko"
            _uso_pend_guarda(pend, now)


# -- los envíos a la tele que aún no se sabe si arrancaron (dtbl106) --
_USO_PEND_FILE = "/tmp/mw_uso_pend.json"
_USO_PEND_S = 360               # si en 6 min no hay vídeo, no arrancó
_USO_PEND_GUARDA = 6 * 3600     # y se recuerda la fuente para sus minutos de carga


def _uso_pend_lee():
    try:
        with open(_USO_PEND_FILE, "r", encoding="utf-8") as f:
            x = _json.load(f)
        return x if isinstance(x, dict) else {}
    except Exception:
        return {}


def _uso_pend_guarda(x, now):
    x = {c: v for c, v in x.items() if (now - float(v.get("ts") or 0)) < _USO_PEND_GUARDA}
    try:
        tmp = "%s.%d.tmp" % (_USO_PEND_FILE, os.getpid())
        with open(tmp, "w", encoding="utf-8") as f:
            _json.dump(x, f)
        os.replace(tmp, _USO_PEND_FILE)
    except Exception:
        pass


def _uso_dia_e(d, hoy):
    return d["dias"].setdefault(hoy, _uso_valida({"dias": {hoy: {}}})["dias"][hoy])


_USO_VISTO = {}                 # por worker: code -> (título, última vez)
_USO_VISTO_S = 600              # el mismo título en 10 min es el mismo vídeo
_USO_VDIAG = {}


_USO_INICIO_MAX_S = 180         # un vídeo "empieza" si va por el principio...
_USO_ASIENTA_S = 90             # ...y los nombres que cambian en su primer minuto y medio son el mismo


def _uso_titulo_nuevo(code, titulo, now, elapsed=0, previo=True):
    """¿Empieza un vídeo NUEVO en esa tele? Devuelve (nuevo, compartido).

    Se recuerdan TODOS los títulos recientes de cada código, no solo el último:
    el 02-11 un mismo código lo tenían 4 teles a la vez (una instalación de Kodi
    copiada) y sus 4 títulos se turnaban cada 3 s -> cada aviso parecía nuevo.
    `compartido`: los títulos se INTERCALAN (vuelve uno que ya estaba cuando
    otro distinto ha llegado hace menos de 15 s): varias teles con un solo
    código. Cambiar de peli deprisa no lo es: el título viejo ya no vuelve.
    (dtbl111) Y un título nuevo no siempre es un vídeo nuevo: al empezar una
    serie Kodi dice primero "The Bear 5x02" y segundos después, con la ficha
    cargada, "The Bear · 5x02". Solo cuenta como inicio si el vídeo va por el
    principio (o la tele no estaba reproduciendo nada: reanudar tras apagar) y
    no hubo otro inicio en los últimos 90 s (salvo un envío nuevo de la web).
    Primero la memoria de este worker (cero E/S casi siempre); si no lo sabe,
    el fichero común, bajo lock, para que el otro worker no lo cuente otra vez."""
    h = _hl.md5(titulo.encode("utf-8")).hexdigest()[:8]
    m = _USO_VISTO.setdefault(code, {})
    prev = m.get(h)
    m[h] = now
    if prev and now - prev < _USO_VISTO_S:
        _USO_VDIAG["mem"] = _USO_VDIAG.get("mem", 0) + 1
        return False, any(k != h and prev < v and now - v < 15 for k, v in m.items())
    for k in [k for k, v in m.items() if now - v > _USO_VISTO_S]:
        m.pop(k, None)
    if len(_USO_VISTO) > 3000:
        for c in [c for c, x in _USO_VISTO.items() if not x or now - max(x.values()) > _USO_VISTO_S]:
            _USO_VISTO.pop(c, None)
    try:
        with _FileLock(_USO_PEND_FILE):
            pend = _uso_pend_lee()
            x = pend.get("t:" + code)
            tt = x.get("tt") if isinstance(x, dict) and isinstance(x.get("tt"), dict) else {}
            tt = {k: float(v) for k, v in tt.items() if now - float(v or 0) < _USO_VISTO_S}
            nuevo = h not in tt
            compartido = (not nuevo) and any(k != h and tt[h] < v and now - v < 15 for k, v in tt.items())
            ui = float((x or {}).get("ui") or 0) if isinstance(x, dict) else 0.0
            if nuevo:
                w = pend.get(code) or {}
                web_nueva = bool(w) and not w.get("hecho") and float(w.get("ts") or 0) > ui
                if (elapsed <= _USO_INICIO_MAX_S or not previo) and \
                        (now - ui >= _USO_ASIENTA_S or web_nueva):
                    ui = now
                else:
                    nuevo = False
                    _USO_VDIAG["asienta"] = _USO_VDIAG.get("asienta", 0) + 1
            tt[h] = now
            if len(tt) > 12:
                tt = dict(sorted(tt.items(), key=lambda kv: kv[1])[-12:])
            pend["t:" + code] = {"ts": now, "tt": tt, "ui": ui}
            _uso_pend_guarda(pend, now)
        _USO_VDIAG["nuevo" if nuevo else "fich"] = _USO_VDIAG.get("nuevo" if nuevo else "fich", 0) + 1
        if compartido:
            _USO_VDIAG["compartido"] = _USO_VDIAG.get("compartido", 0) + 1
        return nuevo, compartido
    except Exception:
        return False, False


_USO_DU_YA = {}                 # por worker: code -> día ya apuntado


def _uso_compartido(code, now):
    """Un código que usan varias teles a la vez: se apunta una vez al día."""
    hoy = _uso_es(now)[0]
    if _USO_DU_YA.get(code) == hoy:
        return
    _USO_DU_YA[code] = hoy
    try:
        with _FileLock(_USO_FILE):
            d = _uso_lee()
            e = _uso_dia_e(d, hoy)
            e["du"] = sorted(set(e.get("du") or []) | {_uso_huella(code)})
            _uso_guarda(d)
        _USO_NUBE["cambios"] += 1
    except Exception:
        pass


def _uso_arranco(code, now=None):
    """La tele de `code` ha empezado un vídeo NUEVO: si venía de un envío de la
    web, ese envío arrancó (y en cuánto); si no, se puso con el mando."""
    if os.environ.get("MW_SIN_USO_EVENTOS") == "1":
        return
    now = _t.time() if now is None else now
    try:
        hoy = _uso_es(now)[0]
        with _FileLock(_USO_PEND_FILE):
            pend = _uso_pend_lee()
            x = pend.get(code)
            web = bool(x) and not x.get("hecho") and (now - float(x.get("ts") or 0)) <= _USO_PEND_S
            if web:
                x["hecho"] = "ok"
                _uso_pend_guarda(pend, now)
            movil = (not web) and (now - float((pend.get("w:" + code) or {}).get("ts") or 0)) <= _USO_MOVIL_S
        with _FileLock(_USO_FILE):
            d = _uso_lee()
            e = _uso_dia_e(d, hoy)
            if web:
                _uso_resuelve_ok(e, x, max(0, int(now - float(x.get("ts") or now))))
            else:
                _uso_suma(e, "pm", "movil" if movil else "mando")
            _uso_guarda(d)
        _USO_NUBE["cambios"] += 1
    except Exception:
        pass


def _uso_suma(e, k, clave, n=1):
    x = e.get(k) if isinstance(e.get(k), dict) else {}
    x[clave] = int(x.get(clave, 0)) + n
    e[k] = x


def _uso_funde(a, b):
    """La unión de dos estados (local y copia). Nunca pierde nada de ninguno."""
    out = _uso_valida(a)
    b = _uso_valida(b)
    out["adm"] = b["adm"] or out["adm"]          # la de la copia manda
    out["desde"] = min(out["desde"], b["desde"])
    out["ult"] = max(out["ult"], b["ult"])
    for dia, eb in b["dias"].items():
        ea = out["dias"].get(dia)
        if not ea:
            out["dias"][dia] = eb
            continue
        # (dtbl111) lo limpiado a mano gana a "el mayor de los dos": si un lado
        # limpió una clave DESPUÉS que el otro, se queda con su valor (o sin ella)
        la, lb = ea.get("lim") or {}, eb.get("lim") or {}
        for k in set(la) | set(lb):
            if la.get(k, 0) == lb.get(k, 0):
                continue
            gana = ea if la.get(k, 0) > lb.get(k, 0) else eb
            for kk in (k, "n" + k):
                if kk in gana:
                    ea[kk] = gana[kk]
                    eb[kk] = gana[kk]
                else:
                    ea.pop(kk, None)
                    eb.pop(kk, None)
        for k in _USO_SETS:
            if isinstance(ea.get(k), list) or isinstance(eb.get(k), list):
                ea[k] = sorted(set(ea.get(k) or []) | set(eb.get(k) or []))
            ea["n" + k] = max(int(ea.get("n" + k) or 0), int(eb.get("n" + k) or 0))
        for k, (forma, tope) in _USO_DIC.items():
            if isinstance(ea.get(k), dict) or isinstance(eb.get(k), dict):
                ea[k] = _uso_dic_funde(forma, ea.get(k) or {}, eb.get(k) or {})
        for k in ("tm", "mu", "nk15"):
            ea[k] = max(ea.get(k, 0), eb.get(k, 0))
        if eb.get("pico", 0) > ea.get("pico", 0):
            ea["pico"], ea["pico_h"] = eb["pico"], eb.get("pico_h", "")
        ea["hp"] = [max(x, y) for x, y in zip(ea["hp"], eb["hp"])]
    for h, (p, u) in b["cj"].items():
        ya = out["cj"].get(h)
        out["cj"][h] = [min(p, ya[0]), max(u, ya[1])] if ya else [p, u]
    for h, ds in b["act"].items():
        out["act"][h] = sorted(set(out["act"].get(h) or []) | set(ds))[-60:]
    return out


def _uso_muestra(now=None, forzar=False):
    """Una foto de este minuto: qué Kodis laten, cuáles tienen un vídeo puesto
    y de cuáles se está mirando la web. Devuelve True si la tomó."""
    now = _t.time() if now is None else now
    try:
        st = _kbstatus_load() or {}
        vivas = [c for c, e in st.items()
                 if (now - float(e.get("ts", 0) or 0)) < 90]
        ips = [str(st[c].get("ih") or "") for c in vivas if st[c].get("ih")]
        np = {c: e.get("np") or {} for c, e in (_kbnow_load() or {}).items()
              if (now - float(e.get("ts", 0) or 0)) < _KB_NOW_TTL and (e.get("np") or {}).get("mw")}
        moviles = [c for c, ts in (_kb_seen_load() or {}).items()
                   if (now - float(ts or 0)) < _KB_SEEN_TTL]
    except Exception:
        return False
    rep = [c for c, x in np.items() if not x.get("paused")]
    hoy, hora, hhmm = _uso_es(now)
    with _FileLock(_USO_FILE):
        d = _uso_lee()
        if not forzar and (now - d["ult"]) < 55:
            return False                          # el otro worker ya la tomó
        e = d["dias"].setdefault(hoy, _uso_valida({"dias": {hoy: {}}})["dias"][hoy])
        for k, lista in (("c", vivas), ("r", list(np)), ("m", moviles)):
            hs = {_uso_huella(c) for c in lista}
            e[k] = sorted(set(e.get(k) or []) | hs)
        e["ip"] = sorted(set(e.get("ip") or []) | set(ips))
        for c in vivas:
            _uso_suma(e, "km", _uso_huella(c))
        for c in rep:
            _uso_suma(e, "rm", _uso_huella(c))
        _uso_muestra_mas(d, e, st, vivas, rep, now, hoy, np)
        if len(rep) > e.get("pico", 0):
            e["pico"], e["pico_h"] = len(rep), hhmm
        e["hp"][hora] = max(e["hp"][hora], len(rep))
        e["tm"] = e.get("tm", 0) + len(rep)       # minutos de tele (uno por muestra)
        try:                                      # (dtbl134) y en el móvil, por servidor
            for x in _vpnow_vivos(now).values():
                if not x.get("pausa"):
                    _uso_suma(e, "vq", str(x.get("srv") or "?")[:20])
        except Exception:
            pass
        e["mu"] = e.get("mu", 0) + 1              # minutos con el relay mirando
        for c in vivas:
            h = _uso_huella(c)
            ya = d["cj"].get(h)
            d["cj"][h] = [ya[0], hoy] if ya else [hoy, hoy]
        d["ult"] = now
        _uso_compacta(d, hoy)
        _uso_guarda(d)
    _USO_NUBE["cambios"] += 1
    return True


# -- la copia cifrada en mw-sync (sus lecturas son públicas) --
def _uso_claves():
    sem = _kv_par()[0]
    if not sem:
        return None, None
    import hmac as _hm
    return (_hm.new(sem, b"mw-uso-cifra-v1", _hl.sha256).digest(),
            _hm.new(sem, b"mw-uso-mac-v1", _hl.sha256).digest())


def _uso_flujo(clave, nonce, n):
    out = bytearray()
    i = 0
    while len(out) < n:
        out += _hl.sha256(clave + nonce + i.to_bytes(8, "big")).digest()
        i += 1
    return bytes(out[:n])


def _uso_cifra(datos, kc, km):
    import hmac as _hm
    nonce = os.urandom(16)
    ks = _uso_flujo(kc, nonce, len(datos))
    ct = (int.from_bytes(datos, "big") ^ int.from_bytes(ks, "big")).to_bytes(len(datos), "big") \
        if datos else b""
    tag = _hm.new(km, nonce + ct, _hl.sha256).digest()
    return nonce + ct + tag


def _uso_descifra(blob, kc, km):
    import hmac as _hm
    if len(blob) < 48:
        return None
    nonce, ct, tag = blob[:16], blob[16:-32], blob[-32:]
    if not _hm.compare_digest(tag, _hm.new(km, nonce + ct, _hl.sha256).digest()):
        return None
    ks = _uso_flujo(kc, nonce, len(ct))
    return (int.from_bytes(ct, "big") ^ int.from_bytes(ks, "big")).to_bytes(len(ct), "big") \
        if ct else b""


def _uso_empaqueta(d, kc, km):
    import base64
    raw = _gzmod.compress(_json.dumps(d, separators=(",", ":")).encode("utf-8"), 6)
    return "u1." + base64.b64encode(_uso_cifra(raw, kc, km)).decode("ascii")


def _uso_desempaqueta(gz, kc, km):
    import base64
    if not (isinstance(gz, str) and gz.startswith("u1.")):
        return None
    try:
        raw = _uso_descifra(base64.b64decode(gz[3:]), kc, km)
        return _uso_valida(_json.loads(_gzmod.decompress(raw).decode("utf-8"))) if raw is not None else None
    except Exception:
        return None


def _uso_nube_lee():
    """La copia, descifrada. None si NO se pudo leer (no es lo mismo que vacía:
    vacía es que aún no hay ninguna)."""
    kc, km = _uso_claves()
    if not kc:
        return None
    try:
        txt, st = _get_con_tope(_USO_SYNC, 10.0)
        if st != 200 or not txt:
            return None
        gz = (_json.loads(txt) or {}).get("gz")
        if not gz:
            return _uso_vacio()
        return _uso_desempaqueta(gz, kc, km)      # None si no es nuestra (no se pisa)
    except Exception:
        return None


def _uso_sube_ya():
    """Leer, fundir y subir la unión (nunca a ciegas). True si la copia quedó."""
    kc, km = _uso_claves()
    if not kc or not _EN_RENDER or os.environ.get("MW_SIN_NUBE") == "1":
        return False
    remoto = _uso_nube_lee()
    if remoto is None:
        _USO_NUBE["fallos"] += 1
        return False
    _USO_NUBE["leida"] = True
    with _FileLock(_USO_FILE):
        d = _uso_funde(_uso_lee(), remoto)
        _uso_compacta(d, _uso_es()[0])
        _uso_guarda(d)
    gz = _uso_empaqueta(d, kc, km)
    if len(gz) <= 900 * 1024 and _post_con_tope(_USO_SYNC, {"gz": gz}, 15.0) == 200:
        _USO_NUBE["subidas"] += 1
        _USO_NUBE["subida_ts"] = _t.time()
        return True
    _USO_NUBE["fallos"] += 1
    return False


def _uso_nube_sube():
    """Cada 10 min como mucho, con cambios, en segundo plano."""
    ahora = _t.time()
    if not _USO_NUBE["leida"] or _USO_NUBE["cambios"] <= 0:
        return
    if (ahora - _USO_NUBE["subida_ts"]) < 600:
        return
    if _USO_NUBE["vuelo"] and (ahora - _USO_NUBE["vuelo"]) < 120:
        return
    _USO_NUBE["vuelo"] = ahora
    _USO_NUBE["subida_ts"] = ahora
    _USO_NUBE["cambios"] = 0

    def _ir():
        try:
            _uso_sube_ya()
        finally:
            _USO_NUBE["vuelo"] = 0.0
    _thr.Thread(target=_ir, daemon=True).start()


def _uso_bucle():
    # primero la copia: hasta tenerla no se sube nada ni se reclama la llave
    for espera in (3, 10, 30, 60, 120, 300):
        if os.environ.get("MW_SIN_NUBE") == "1" or not _EN_RENDER:
            break
        got = _uso_nube_lee()
        if got is not None:
            with _FileLock(_USO_FILE):
                _uso_guarda(_uso_funde(_uso_lee(), got))
            _USO_NUBE["leida"] = True
            _USO_NUBE["bajadas"] += 1
            break
        _t.sleep(espera)
    reintento = _t.time()
    while True:
        try:
            _uso_muestra()
            _uso_nube_sube()
            # ¿la copia no se pudo leer al arrancar? se vuelve a mirar cada
            # 10 min: sin ella no se sube nada (pisaría la buena)
            if not _USO_NUBE["leida"] and _EN_RENDER and os.environ.get("MW_SIN_NUBE") != "1" \
                    and (_t.time() - reintento) >= 600:
                reintento = _t.time()
                got = _uso_nube_lee()
                if got is not None:
                    with _FileLock(_USO_FILE):
                        _uso_guarda(_uso_funde(_uso_lee(), got))
                    _USO_NUBE["leida"] = True
                    _USO_NUBE["bajadas"] += 1
        except Exception:
            pass
        _t.sleep(30 + _rnd_uso.random() * 5)


import random as _rnd_uso      # noqa: E402


_USO_FUENTES = ("dt", "dx", "et", "wf", "cb")


def _uso_calidad(q):
    q = str(q or "").lower()
    if re.search(r"2160|4k|uhd", q):
        return "4k"
    if "1080" in q:
        return "1080"
    if "720" in q:
        return "720"
    return "otra" if q.strip() else "nd"


_USO_CAP_RE = re.compile(r"(?i)\s*[-·:(]*\s*(\b\d{1,2}x\d{1,3}\b.*|\bS\d{1,2}\s*E\d{1,3}\b.*|\btemporada\s*\d+.*|\(\d{4}\)\s*)$")


_USO_ETIQ_RE = re.compile(
    r"(?i)\b(2160p|1080p|720p|480p|4k|uhd|hdr10?\+?|hdr|dv|bluray|blu-ray|bdrip|brrip|web-?dl|webrip|"
    r"hdtv|dvdrip|remux|x26[45]|h\.?26[45]|hevc|avc|aac|ac3|dts(-hd)?|atmos|ddp?5\.1|5\.1|10bit|"
    r"castellano|spanish|esp|dual|multi|subs?|vose|proper|repack|microhd|fullbluray)\b.*$")


_USO_TIT_BASURA = {"reproducir", "reproduciendo", "play", "playing", "video", "vídeo",
                   "sin título", "untitled", "unknown", "desconocido", "stream"}


def _uso_titulo(t):
    """El título sin el capítulo ni las etiquetas: 'The Bear · 5x02' -> 'The
    Bear'; 'Resident.Evil.2002.1080p.BluRay.mkv' -> 'Resident Evil'."""
    t = re.sub(r"\s+", " ", str(t or "")).strip()
    t = re.sub(r"(?i)\.(mkv|mp4|avi|m4v|mov|ts)$", "", t)
    fichero = " " not in t and bool(re.search(r"[._]", t))
    if fichero:                                       # nombre de fichero
        t = re.sub(r"[._]+", " ", t)
    t = re.sub(r"\[[^\]]*\]", " ", t)
    t = _USO_ETIQ_RE.sub("", t)
    t = re.sub(r"\s+", " ", t).strip()
    # el año: entre paréntesis siempre; suelto solo en nombres de fichero
    # ("Blade Runner 2049" o "1917" son títulos)
    t = re.sub(r"\s*[(\[]\s*(19|20)\d\d\s*[)\]]\s*$", "", t) or t
    if fichero:
        t = re.sub(r"\s+(19|20)\d\d$", "", t) or t
    t = _USO_CAP_RE.sub("", t).strip(" -·:")
    t = re.sub(r"[\x00-\x1f<>]", "", t)
    if t.lower() in _USO_TIT_BASURA:          # lo que algunos addons ponen de título
        return ""
    return t[:60]


def _uso_envio(fuente, q, code="", titulo="", tipo="", espera=True):
    """Una reproducción mandada desde la web: fuente, calidad, película o serie
    y el título (sumado entre todos: nunca se guarda qué tele lo pidió, solo
    una huella corta para no contar dos veces a la misma) (dtbl104-106)."""
    try:
        now = _t.time()
        hoy = _uso_es(now)[0]
        f = fuente if fuente in _USO_FUENTES else "otra"
        if code and espera:     # (dtbl111) a una tele apagada no se le espera
            with _FileLock(_USO_PEND_FILE):
                pend = _uso_pend_lee()
                x = pend.get(code)
                cambio = x if (x and not x.get("hecho")
                               and (now - float(x.get("ts") or 0)) <= _USO_PEND_S) else None
                pend[code] = {"f": f, "ts": now}
                _uso_pend_guarda(pend, now)
        else:
            cambio = None
        with _FileLock(_USO_FILE):
            d = _uso_lee()
            e = _uso_dia_e(d, hoy)
            _uso_suma(e, "rf", f)
            _uso_suma(e, "rq", _uso_calidad(q))
            if cambio:
                _uso_suma(e, "cb", cambio.get("f") or "otra")
            if tipo in ("movie", "tv"):
                _uso_suma(e, "rk", tipo)
            _uso_guarda(d)
        _USO_NUBE["cambios"] += 1
    except Exception:
        pass


_USO_BQ_IP = {}                  # por worker: ip -> [inicio de la ventana, cuántas]


def _uso_busqueda_norm(q):
    import unicodedata as _ud
    q = _ud.normalize("NFKD", str(q or "").lower())
    q = "".join(ch for ch in q if not _ud.combining(ch))
    q = re.sub(r"[^a-z0-9 ]+", " ", q)
    return re.sub(r"\s+", " ", q).strip()[:60]


def _uso_arranca():
    if os.environ.get("MW_SIN_USO") == "1":
        return
    try:
        _thr.Thread(target=_uso_bucle, daemon=True).start()
    except Exception:
        pass


def _uso_llave_de(req):
    return str(req.headers.get("X-MW-Uso") or req.args.get("k") or "").strip()[:80]


def _uso_es_admin(req):
    k = _uso_llave_de(req)
    if not k:
        return False
    adm = _uso_lee()["adm"]
    import hmac as _hm
    return bool(adm) and _hm.compare_digest(_hl.sha256(k.encode("utf-8")).hexdigest(), adm)


@app.post("/uso/alta")
def uso_alta():
    """Reclamar la llave. Solo una vez, solo recién arrancado, y solo si se sabe
    seguro que no hay otra (la copia se leyó)."""
    en_local = os.environ.get("MW_SIN_NUBE") == "1" or not _EN_RENDER
    if (_t.time() - _USO_T0) > _USO_ALTA_S:
        return jsonify({"ok": False, "error": "cerrado"}), 403
    if not en_local and not _USO_NUBE["leida"]:
        return jsonify({"ok": False, "error": "aun no"}), 503
    import secrets as _sec
    llave = _sec.token_urlsafe(18)
    with _FileLock(_USO_FILE):
        d = _uso_lee()
        if d["adm"]:
            return jsonify({"ok": False, "error": "ya hay llave"}), 403
        d["adm"] = _hl.sha256(llave.encode("utf-8")).hexdigest()
        _uso_guarda(d)
    if not en_local and not _uso_sube_ya():
        with _FileLock(_USO_FILE):            # sin copia, no hay llave
            d = _uso_lee()
            d["adm"] = ""
            _uso_guarda(d)
        return jsonify({"ok": False, "error": "sin copia"}), 503
    return jsonify({"ok": True, "k": llave})


# ==== MAPA de /uso (dtbl123): dónde hay una tele viendo algo ===================
# Render no trae la ciudad (solo CF-IPCountry), así que la ubicación APROXIMADA
# de cada conexión la pregunta un hilo a servicios de geolocalización, en cadena
# (si uno falla o limita, el siguiente). Nunca desde el latido: el latido solo
# apunta la IP en memoria y sigue. Se guarda huella-de-conexión -> ciudad
# (redondeada a la ciudad que dice el servicio): ni IPs ni códigos.
_GEO_FILE = "/tmp/mw_geo.json"
_GEO_TTL = 7 * 86400            # se vuelve a mirar cada semana
_GEO_KO_S = 1800                # si nadie supo ubicarla, no se insiste en 30 min
_GEO_PEND = {}                  # ih -> ip (solo en memoria, de este worker)
_GEO_LOCK = _thr.Lock()
_GEO_HILO = {"vivo": False}
_GEO_KO = {}                    # ih -> ts del último intento fallido (memoria)


def _geo_lee():
    try:
        with open(_GEO_FILE, "r", encoding="utf-8") as f:
            d = _json.load(f) or {}
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


def _geo_guarda_uno(ih, la, lo, ciudad, pais=""):
    with _GEO_LOCK:
        d = _geo_lee()               # el otro worker también escribe: fundir
        now = _t.time()
        d = {k: v for k, v in d.items()
             if isinstance(v, list) and len(v) >= 4 and now - float(v[3] or 0) < 30 * 86400}
        d[ih] = [round(float(la), 2), round(float(lo), 2), str(ciudad or "")[:40], now,
                 str(pais or "")[:2]]
        if len(d) > 3000:
            d = dict(sorted(d.items(), key=lambda kv: kv[1][3])[-3000:])
        try:
            tmp = "%s.%d.tmp" % (_GEO_FILE, os.getpid())
            with open(tmp, "w", encoding="utf-8") as f:
                _json.dump(d, f)
            os.replace(tmp, _GEO_FILE)
        except Exception:
            pass


def _geo_busca(ip):
    """(lat, lon, ciudad, país) o None. Tres servicios, el primero que sepa."""
    def _num(x):
        try:
            v = float(x)
            return v if v == v else None
        except Exception:
            return None

    def _ipwho(t):
        j = _json.loads(t)
        if j.get("success") is False:
            return None
        return _num(j.get("latitude")), _num(j.get("longitude")), j.get("city"), j.get("country_code")

    def _ipinfo(t):
        j = _json.loads(t)
        la, _, lo = str(j.get("loc") or "").partition(",")
        return _num(la), _num(lo), j.get("city"), j.get("country")

    def _geojs(t):
        j = _json.loads(t)
        return _num(j.get("latitude")), _num(j.get("longitude")), j.get("city"), j.get("country_code")

    q = urlquote(ip, safe="")
    for url, lee in (("https://ipwho.is/" + q, _ipwho),
                     ("https://ipinfo.io/" + q + "/json", _ipinfo),
                     ("https://get.geojs.io/v1/ip/geo/" + q + ".json", _geojs)):
        try:
            txt, st = _get_con_tope(url, 6.0, headers={"Accept": "application/json",
                                                       "User-Agent": "MejorWolf/1"})
            if st != 200 or not txt:
                continue
            r = lee(txt)
            if r and r[0] is not None and r[1] is not None and (r[0] or r[1]) \
                    and -90 <= r[0] <= 90 and -180 <= r[1] <= 180:
                return r
        except Exception:
            continue
    return None


def _geo_hilo():
    try:
        while True:
            with _GEO_LOCK:
                if not _GEO_PEND:
                    _GEO_HILO["vivo"] = False
                    return
                ih, ip = _GEO_PEND.popitem()
            r = _geo_busca(ip)
            if r:
                _geo_guarda_uno(ih, r[0], r[1], r[2], r[3])
                _GEO_KO.pop(ih, None)
            else:
                _GEO_KO[ih] = _t.time()
            _t.sleep(1.5)            # sin ráfagas: los servicios gratis limitan
    except Exception:
        with _GEO_LOCK:
            _GEO_HILO["vivo"] = False


def _geo_apunta(ih, ip):
    """Desde el latido: ¿hace falta ubicar esta conexión? Sin red aquí."""
    if not ih or not ip or os.environ.get("MW_SIN_GEO") == "1":
        return
    try:
        import ipaddress as _ipa
        a = _ipa.ip_address(ip)
        if a.is_private or a.is_loopback or a.is_reserved or a.is_link_local:
            return
    except Exception:
        return
    now = _t.time()
    if now - _GEO_KO.get(ih, 0) < _GEO_KO_S:
        return
    v = _geo_lee().get(ih)
    if isinstance(v, list) and len(v) >= 4 and now - float(v[3] or 0) < _GEO_TTL:
        return
    with _GEO_LOCK:
        if len(_GEO_PEND) < 200:
            _GEO_PEND[ih] = ip
        if _GEO_HILO["vivo"]:
            return
        _GEO_HILO["vivo"] = True
    try:
        _thr.Thread(target=_geo_hilo, daemon=True, name="mw-geo").start()
    except Exception:
        with _GEO_LOCK:
            _GEO_HILO["vivo"] = False


def _uso_mapa(now=None):
    """Puntos del mapa: por ciudad, cuántas teles viendo, en pausa y Kodis
    encendidos. Ni códigos ni títulos."""
    now = _t.time() if now is None else now
    st = _kbstatus_load() or {}
    nw = {c: (e.get("np") or {}) for c, e in (_kbnow_load() or {}).items()
          if (now - float(e.get("ts", 0) or 0)) < _KB_NOW_TTL and (e.get("np") or {}).get("mw")}
    geo = _geo_lee()
    pts, sin = {}, {"viendo": 0, "kodis": 0}
    codigos = {c for c, e in st.items() if (now - float(e.get("ts", 0) or 0)) < 90} | set(nw)
    for c in codigos:
        np_ = nw.get(c)
        est = "v" if np_ and not np_.get("paused") else ("p" if np_ else "k")
        g = geo.get((st.get(c) or {}).get("ih") or "")
        if not (isinstance(g, list) and len(g) >= 4):
            sin["kodis"] += 1
            if est == "v":
                sin["viendo"] += 1
            continue
        k = (g[0], g[1])
        p = pts.setdefault(k, {"la": g[0], "lo": g[1], "c": g[2] or "", "pa": (g[4] if len(g) > 4 else "") or "",
                                "v": 0, "p": 0, "k": 0})
        p[est] += 1
    return {"puntos": sorted(pts.values(), key=lambda p: (-p["v"], -p["p"], -p["k"])),
            "sin_ubicar": sin}


# (dtbl134) Lo que se ve en el PROPIO móvil ("Aquí", dtbl131) también sale en
# /uso. El reproductor de la web late cada 30 s mientras está abierto; si deja
# de latir (cerrado, sin red, el móvil bloqueado) desaparece solo. Por sesión
# de reproducción un id al azar: ni código, ni IP, ni nada guardado en el móvil.
_VP_NOW_FILE = "/tmp/mw_vp_now.json"
_VP_NOW_TTL = 75


def _vpnow_load():
    try:
        with open(_VP_NOW_FILE, "r", encoding="utf-8") as f:
            return _json.load(f) or {}
    except Exception:
        return {}


def _vpnow_save(d):
    try:
        tmp = "%s.%d.tmp" % (_VP_NOW_FILE, os.getpid())
        with open(tmp, "w", encoding="utf-8") as f:
            _json.dump(d, f)
        os.replace(tmp, _VP_NOW_FILE)
    except Exception:
        pass


def _vpnow_vivos(now=None):
    now = _t.time() if now is None else now
    return {k: v for k, v in (_vpnow_load() or {}).items()
            if isinstance(v, dict) and (now - float(v.get("ts", 0) or 0)) < _VP_NOW_TTL}


@app.post("/vp/latido")
def vp_latido():
    body = request.get_json(silent=True, force=True) or {}
    if not isinstance(body, dict):
        return jsonify({"ok": False}), 400
    lid = str(body.get("id") or "")
    if not re.match(r"^[0-9a-f]{16}$", lid):
        return jsonify({"ok": False}), 400
    now = _t.time()

    def _n(x):
        try:
            return max(0, min(86400, int(float(x or 0))))
        except Exception:
            return 0
    t = re.sub(r"\s+", " ", re.sub(r"[\x00-\x1f<>]", "", str(body.get("t") or ""))).strip()[:140]
    srv = re.sub(r"[^A-Za-z0-9 ]", "", str(body.get("srv") or "")).strip()[:20] or "?"
    pausa, fin, ini = bool(body.get("pausa")), bool(body.get("fin")), bool(body.get("ini"))
    with _FileLock(_VP_NOW_FILE):
        d = _vpnow_vivos(now)
        if fin:
            d.pop(lid, None)
        elif lid in d or len(d) < 300:
            d[lid] = {"t": t, "srv": srv, "pos": _n(body.get("pos")), "dur": _n(body.get("dur")),
                      "pausa": pausa, "ts": now}
        else:
            ini = False
        _vpnow_save(d)
    if ini and not fin:          # un vídeo que empieza en el móvil, por servidor
        try:
            with _FileLock(_USO_FILE):
                du = _uso_lee()
                _uso_suma(_uso_dia_e(du, _uso_es(now)[0]), "vqv", srv)
                _uso_guarda(du)
            _USO_NUBE["cambios"] += 1
        except Exception:
            pass
    return jsonify({"ok": True})


def _uso_ahora(now=None):
    now = _t.time() if now is None else now
    np = [e.get("np") or {} for e in (_kbnow_load() or {}).values()
          if (now - float(e.get("ts", 0) or 0)) < _KB_NOW_TTL and (e.get("np") or {}).get("mw")]
    vivas = [e for e in (_kbstatus_load() or {}).values()
             if (now - float(e.get("ts", 0) or 0)) < 90]
    vers = {}
    for e in vivas:
        vers[e.get("v") or "?"] = vers.get(e.get("v") or "?", 0) + 1
    moviles = sum(1 for ts in (_kb_seen_load() or {}).values()
                  if (now - float(ts or 0)) < _KB_SEEN_TTL)
    lista = sorted(({"t": _uso_titulo(x.get("title")) or (
                        "Serie sin nombre" if re.search(r"\b\d{1,2}x\d{1,3}\b", str(x.get("title") or "")) else "Sin título"),
                     "cap": (re.search(r"\b(\d{1,2}x\d{1,3})\b", str(x.get("title") or "")) or [None, ""])[1],
                     "min": int(x.get("elapsed") or 0) // 60, "de": int(x.get("total") or 0) // 60,
                     "pausa": bool(x.get("paused"))} for x in np),
                   key=lambda z: (z["pausa"], z["t"].lower()))
    try:
        vp = list(_vpnow_vivos(now).values())
    except Exception:
        vp = []
    lista += sorted(({"t": _uso_titulo(re.sub(r"\b\d{1,2}x\d{1,3}\b", "", x.get("t") or "")) or "Sin título",
                      "cap": (re.search(r"\b(\d{1,2}x\d{1,3})\b", str(x.get("t") or "")) or [None, ""])[1],
                      "min": int(x.get("pos") or 0) // 60, "de": int(x.get("dur") or 0) // 60,
                      "pausa": bool(x.get("pausa")), "aqui": 1, "srv": x.get("srv") or ""} for x in vp),
                    key=lambda z: (z["pausa"], z["t"].lower()))
    return {"viendo": sum(1 for x in np if not x.get("paused")),
            "en_pausa": sum(1 for x in np if x.get("paused")),
            "movil": sum(1 for x in vp if not x.get("pausa")),
            "movil_pausa": sum(1 for x in vp if x.get("pausa")),
            "kodis": len(vivas), "webs": moviles, "versiones": vers, "lista": lista}


@app.get("/uso/auditoria")
def uso_auditoria():
    """(dtbl116) Los datos en bruto detrás de cada número, para comprobarlos.
    Solo el dueño, y solo huellas cortas: ni códigos ni IP."""
    if not _uso_es_admin(request):
        return jsonify({"ok": False, "error": "privado"}), 401
    now = _t.time()
    if not _USO_ORDENES.get("desde"):
        _USO_ORDENES["desde"] = now
    st = _kbstatus_load() or {}
    npd = _kbnow_load() or {}
    vivos = []
    for c, e in st.items():
        edad = now - float(e.get("ts", 0) or 0)
        if edad > 600:
            continue
        dg = e.get("diag") or {}
        x = npd.get(c) or {}
        vivos.append({"k": _uso_huella(c)[:5], "ip": str(e.get("ih") or "")[:5], "v": e.get("v"),
                      "edad": int(edad), "dev": e.get("dev"), "bids": len(e.get("bids") or {}),
                      "res": dg.get("res"), "cach": dg.get("cach"),
                      "np": bool((x.get("np") or {}).get("mw")) and (now - float(x.get("ts", 0) or 0)) < _KB_NOW_TTL})
    vivos.sort(key=lambda z: (z["ip"], z["k"]))
    d = _uso_lee()
    hoy = _uso_es(now)[0]
    eh = d["dias"].get(hoy) or {}
    km, ki, cj = eh.get("km") or {}, eh.get("ki") or {}, d["cj"]
    por_ip = {}
    for h, ip in ki.items():
        por_ip.setdefault(ip[:5], []).append(h)
    kodis_hoy = []
    for h in sorted(set(eh.get("c") or [])):
        kodis_hoy.append({"k": h[:5], "min_encendido": km.get(h), "ip": (ki.get(h) or "")[:5],
                          "primer_dia": (cj.get(h) or ["?"])[0], "vio_algo": h in set(eh.get("r") or [])})
    return jsonify({"ok": True, "pid": os.getpid(), "hoy": hoy,
                    "vivos": vivos, "n_vivos": len(vivos),
                    "kodis_hoy": kodis_hoy,
                    "conexiones_con_varios_kodis_hoy": {ip: len(hs) for ip, hs in por_ip.items() if len(hs) > 1},
                    "ordenes_web_este_worker": _USO_ORDENES,
                    "uptime_s": int(now - _USO_T0)})


@app.post("/uso/limpia")
def uso_limpia():
    """El dueño borra datos que se sabe que están mal (dtbl111). Queda anotado
    en el día (lim) para que la copia de la nube no los devuelva."""
    if not _uso_es_admin(request):
        return jsonify({"ok": False, "error": "privado"}), 401
    body = request.get_json(silent=True) or {}
    dia = str(body.get("dia") or "")
    claves = [str(k) for k in (body.get("claves") or []) if isinstance(k, str)]
    validas = set(_USO_DIC) | set(_USO_SETS) | {"tm", "pico", "hp"}
    claves = [k for k in claves if k in validas and k != "lim"]
    if not re.match(r"^\d{4}-\d\d-\d\d$", dia) or not claves:
        return jsonify({"ok": False, "error": "dia o claves"}), 400
    now = _t.time()
    with _FileLock(_USO_FILE):
        d = _uso_lee()
        e = d["dias"].get(dia)
        if not e:
            return jsonify({"ok": False, "error": "sin ese dia"}), 404
        for k in claves:
            e.pop(k, None)
            e.pop("n" + k, None)
            e.setdefault("lim", {})[k] = int(now)
        _uso_guarda(d)
    _USO_NUBE["cambios"] += 1
    ok = _uso_sube_ya() if _EN_RENDER and os.environ.get("MW_SIN_NUBE") != "1" else True
    return jsonify({"ok": True, "limpias": claves, "nube": bool(ok)})


@app.post("/uso/busca")
def uso_busca():
    """La web dice qué se ha buscado y cuántos resultados salieron (dtbl106).
    Sin código ni nada de quién: solo el texto, sumado entre todos."""
    try:
        body = request.get_json(silent=True) or {}
    except Exception:
        body = {}
    q = _uso_busqueda_norm(body.get("q"))
    try:
        n = max(0, int(body.get("n") or 0))
    except Exception:
        n = 0
    if len(q) < 2:
        return ("", 204)
    ip = (request.headers.get("True-Client-IP") or request.headers.get("CF-Connecting-IP")
          or request.headers.get("X-Forwarded-For", "").split(",")[0]
          or request.remote_addr or "?").strip()
    now = _t.time()
    v = _USO_BQ_IP.get(ip)
    if not v or now - v[0] > 600:
        v = [now, 0, set()]
        _USO_BQ_IP[ip] = v
    if v[1] >= 40 or q in v[2]:          # nada de inflar: 40 en 10 min y cada una una vez
        return ("", 204)
    v[1] += 1
    v[2].add(q)
    if len(_USO_BQ_IP) > 2000:
        for k in [k for k, x in _USO_BQ_IP.items() if now - x[0] > 600]:
            _USO_BQ_IP.pop(k, None)
    try:
        hoy = _uso_es(now)[0]
        with _FileLock(_USO_FILE):
            d = _uso_lee()
            e = _uso_dia_e(d, hoy)
            bq = e.setdefault("bq", {})
            if q in bq or len(bq) < 400:
                x = bq.setdefault(q, [0, 0])
                x[0] += 1
                if n == 0:
                    x[1] += 1
                _uso_guarda(d)
        _USO_NUBE["cambios"] += 1
    except Exception:
        pass
    return ("", 204)


def _uso_semana(d, base, n=7):
    """Lo sumado de los últimos n días: búsquedas y lo más puesto."""
    import datetime as _dtm
    bq, vt, vm = {}, {}, {}
    for i in range(n):
        e = d["dias"].get((base - _dtm.timedelta(days=i)).isoformat()) or {}
        for q, (a, b) in (e.get("bq") or {}).items():
            x = bq.setdefault(q, [0, 0])
            x[0] += a
            x[1] += b
        for t, hs in (e.get("vt") or {}).items():
            vt[t] = vt.get(t, 0) + len(hs)
        for t, k in (e.get("vtn") or {}).items():
            vt[t] = vt.get(t, 0) + k
        for t, k in (e.get("vm") or {}).items():
            vm[t] = vm.get(t, 0) + k
    top = sorted(bq.items(), key=lambda kv: (-kv[1][0], kv[0]))[:25]
    sin = sorted(((q, x) for q, x in bq.items() if x[1] > 0),
                 key=lambda kv: (-kv[1][1], kv[0]))[:25]
    return {"buscadas": [[q, x[0], x[1]] for q, x in top],
            "sin_nada": [[q, x[1]] for q, x in sin],
            "total_busquedas": sum(x[0] for x in bq.values()),
            "vistos": [[t, k, round(vm.get(t, 0) / 60.0, 1)]
                       for t, k in sorted(vt.items(), key=lambda kv: (-kv[1], -vm.get(kv[0], 0), kv[0]))[:20]]}


def _uso_crece(d, base):
    """Quién llega, quién se queda y quién se va (por los días de cada Kodi)."""
    import datetime as _dtm
    hoy_n = base.toordinal()
    try:
        desde_n = _dtm.date.fromisoformat(d["desde"]).toordinal()
    except Exception:
        desde_n = hoy_n
    fieles = siguen = viejos = fueron = 0
    for h, ds in d["act"].items():
        ult7 = sum(1 for z in ds if hoy_n - z < 7)
        if ult7 >= 4:
            fieles += 1
        primero = ds[0]
        cj = d["cj"].get(h)
        if cj:
            try:
                primero = min(primero, _dtm.date.fromisoformat(cj[0]).toordinal())
            except Exception:
                pass
        if hoy_n - primero >= 7 and primero > desde_n:
            viejos += 1
            if ult7:
                siguen += 1
        if 7 < hoy_n - ds[-1] <= 30:
            fueron += 1
    return {"medidos": len(d["act"]), "fieles": fieles, "siguen": siguen,
            "llegaron_hace_7": viejos, "se_fueron": fueron,
            "dias_medidos": hoy_n - desde_n + 1}


@app.get("/uso/datos")
def uso_datos():
    d = _uso_lee()
    if not d["adm"] and not _USO_NUBE["leida"] and _EN_RENDER \
            and os.environ.get("MW_SIN_NUBE") != "1":
        return jsonify({"ok": False, "error": "arrancando"}), 503
    if not _uso_es_admin(request):
        return jsonify({"ok": False, "error": "privado"}), 401
    now = _t.time()
    hoy = _uso_es(now)[0]
    import datetime as _dtm
    base = _dtm.date.fromisoformat(hoy)

    def _activos(n):
        lim = (base - _dtm.timedelta(days=n - 1)).isoformat()
        return sum(1 for p, u in d["cj"].values() if u >= lim)
    dias = []
    for i in range(29, -1, -1):
        dia = (base - _dtm.timedelta(days=i)).isoformat()
        e = d["dias"].get(dia)
        if dia < d["desde"]:
            continue
        dias.append({"dia": dia, "kodis": _uso_cuenta(e, "c") if e else 0,
                     "teles": _uso_cuenta(e, "r") if e else 0,
                     "webs": _uso_cuenta(e, "m") if e else 0,
                     "casas": _uso_cuenta(e, "ip") if e else 0,
                     "compartidos": _uso_cuenta(e, "du") if e else 0,
                     "cortos": _uso_cortos(e) if e else 0,
                     "km_n": len((e or {}).get("km") or {}),
                     "fuentes": (e or {}).get("rf") or {},
                     "nuevos": sum(1 for p_, u_ in d["cj"].values() if p_ == dia) if dia > d["desde"] else None,
                     "calidad": (e or {}).get("rq") or {},
                     "pico": (e or {}).get("pico", 0), "pico_h": (e or {}).get("pico_h", ""),
                     "horas": round((e or {}).get("tm", 0) / 60.0, 1),
                     "medido_min": (e or {}).get("mu", 0)})
    eh = d["dias"].get(hoy) or {}
    rm = sorted((eh.get("rm") or {}).values())
    try:
        publicada = _ver_publicada()
    except Exception:
        publicada = ""
    def _cuenta_dic(x, i):
        o = {}
        for v in (x or {}).values():
            k = (str(v).split("|") + ["", ""])[i] or "?"
            o[k] = o.get(k, 0) + 1
        return o
    serv = {}
    for f in set(eh.get("ok") or {}) | set(eh.get("ko") or {}) | set(eh.get("cb") or {}) | set(eh.get("bf") or {}):
        ta = (eh.get("ta") or {}).get(f) or [0, 0]
        bf = (eh.get("bf") or {}).get(f) or [0, 0]
        serv[f] = {"ok": (eh.get("ok") or {}).get(f, 0), "ko": (eh.get("ko") or {}).get(f, 0),
                   "cambio": (eh.get("cb") or {}).get(f, 0),
                   "seg_medio": round(ta[0] / ta[1]) if ta[1] else None,
                   "tramos": (eh.get("tb") or {}).get(f) or [0] * 5,
                   "min_cargando": bf[0], "min_viendo": bf[1]}
    out_mas = {"servicio": serv, "como": eh.get("pm") or {}, "tipo": eh.get("rk") or {},
               "resolucion": eh.get("rs") or {},
               "aparatos": _cuenta_dic(eh.get("dv"), 0) if eh.get("dv") else (eh.get("dvn") or {}),
               "kodi": _cuenta_dic(eh.get("dv"), 1) if eh.get("dv") else (eh.get("kvn") or {}),
               "paises": _cuenta_dic(eh.get("pa"), 0) if eh.get("pa") else (eh.get("pan") or {}),
               "semana": _uso_semana(d, base), "crece": _uso_crece(d, base),
               "aqui": {"min": eh.get("vq") or {}, "vistos": eh.get("vqv") or {}},
               "cab": sorted(_USO_CAB)}
    out = {"ok": True, "ahora": _uso_ahora(now), "hoy": hoy, "publicada": publicada,
           "dia_parcial": hoy == _USO_DIA_ARRANQUE,
           "med_min_tele": rm[len(rm) // 2] if rm else 0,
           "ip_medidas": isinstance(eh.get("ip"), list) and bool(eh.get("ip")),
           "horas_hoy": eh.get("hp") or [0] * 24, "dias": dias,
           "activos_7": _activos(7), "activos_30": _activos(30),
           "nuevos_7": sum(1 for p, u in d["cj"].values()
                           if p >= (base - _dtm.timedelta(days=6)).isoformat() and p > d["desde"]),
           "conocidos": len(d["cj"]), "desde": d["desde"],
           "copia": {"leida": _USO_NUBE["leida"], "subidas": _USO_NUBE["subidas"],
                     "fallos": _USO_NUBE["fallos"],
                     "hace_s": int(now - _USO_NUBE["subida_ts"]) if _USO_NUBE["subida_ts"] else None},
           "build": BUILD}
    out.update(out_mas)
    try:
        out["mapa"] = _uso_mapa(now)
    except Exception:
        out["mapa"] = {"puntos": [], "sin_ubicar": {"viendo": 0, "kodis": 0}, "error": True}
    try:
        out["avisos"] = _cb_avisos()         # Cinubo: cuentas, dirección, Telegram (dtbl119)
    except Exception:
        out["avisos"] = []
    r = jsonify(out)
    r.headers["Cache-Control"] = "no-store"
    return r


@app.get("/uso")
def uso_pagina():
    r = Response(_USO_PAGE, mimetype="text/html")
    r.headers["Cache-Control"] = "no-store"
    r.headers["X-Robots-Tag"] = "noindex, nofollow"
    r.headers["Referrer-Policy"] = "no-referrer"
    return r


